window.LSA_DATA = {"meta":{"name":"團體協約法","en":"Collective Agreement Act","pcode":"N0020006","modified":"20150701","modifiedRoc":"104.07.01","source":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0020006"},"app":{"id":"cba-codex","db":"cba-codex","short":"團體協約法典","annPos":"b","refTap":"peek","enact":"民國 19 年 10 月 28 日制定公布","flags":{},"notes":{"5":[{"r":[{"l":0,"s":13,"e":16}],"t":"原為「行政院勞工委員會」；行政院103.02.14公告自103.02.17起改由勞動部管轄，104.07.01修正公布本條（104.07.03施行）","p":"a","c":"r","src":"全國法規資料庫・團體協約法沿革"}],"6":[{"r":[{"l":12,"s":0,"e":19}],"t":"本項（第5項）為103.06.04修正公布時增訂，103.07.01施行","p":"a","c":"r","src":"全國法規資料庫・團體協約法沿革"}],"10":[{"r":[{"l":4,"s":67,"e":75}],"t":"自101.02.06起改由「行政院人事行政總處」管轄（行政院101.02.03院臺規字第1010122318號公告）","p":"a","c":"r","src":"全國法規資料庫・團體協約法沿革"}],"34":[{"r":[{"l":0,"s":0,"e":13}],"t":"97.01.09修正全文，定自100.05.01施行；103.06.04修正第6條，定自103.07.01施行；104.07.01修正第5條，定自104.07.03施行","p":"a","c":"r","src":"全國法規資料庫・團體協約法沿革"}]},"intro":"藍字為本法條號、綠字為其他法律（工會法、勞資爭議處理法、民法…）：點一下即以小字顯示該條文字。紅色小字為註記，用手指或 Apple Pencil 點一下即可隱藏／顯示。","disclaimer":"條文、歷次修正條文及工會法、勞資爭議處理法、勞動基準法、民法等相關條文取自法務部全國法規資料庫；97 年全文修正之新舊條次對應係依條文內容整理，僅供比較參考。判決、裁決要旨係摘錄自司法院裁判書系統之判決原文（附原文連結），函釋為法院判決中引用之主管機關函號與內容摘錄。本工具僅供學習參考，實際引用請以原文為準。個人註記僅儲存在本裝置，請定期於「設定」匯出備份。","others":[{"name":"勞基法法典","href":"../"}]},"chapters":["第 一 章 總則","第 二 章 團體協約之協商及簽訂","第 三 章 團體協約之內容及限制","第 四 章 團體協約之效力","第 五 章 團體協約之存續期間","第 六 章 罰則","第 七 章 附則"],"articles":[{"no":"1","ch":"第 一 章 總則","lines":[{"i":0,"t":"為規範團體協約之協商程序及其效力，穩定勞動關係，促進勞資和諧，保障勞資權益，特制定本法。"}]},{"no":"2","ch":"第 一 章 總則","lines":[{"i":0,"t":"本法所稱團體協約，指雇主或有法人資格之雇主團體，與依工會法成立之工會，以約定勞動關係及相關事項為目的所簽訂之書面契約。"}]},{"no":"3","ch":"第 一 章 總則","lines":[{"i":0,"t":"團體協約違反法律強制或禁止之規定者，無效。但其規定並不以之為無效者，不在此限。"}]},{"no":"4","ch":"第 一 章 總則","lines":[{"i":0,"t":"有二個以上之團體協約可適用時，除效力發生在前之團體協約有特別約定者外，優先適用職業範圍較為狹小或職務種類較為特殊之團體協約；團體協約非以職業或職務為規範者，優先適用地域或人數適用範圍較大之團體協約。"}]},{"no":"5","ch":"第 一 章 總則","lines":[{"i":0,"t":"本法所稱主管機關：在中央為勞動部；在直轄市為直轄市政府；在縣（市）為縣（市）政府。"}]},{"no":"6","ch":"第 二 章 團體協約之協商及簽訂","lines":[{"i":0,"t":"勞資雙方應本誠實信用原則，進行團體協約之協商；對於他方所提團體協約之協商，無正當理由者，不得拒絕。"},{"i":0,"t":"勞資之一方於有協商資格之他方提出協商時，有下列情形之一，為無正當理由："},{"i":4,"t":"一、對於他方提出合理適當之協商內容、時間、地點及進行方式，拒絕進行協商。"},{"i":4,"t":"二、未於六十日內針對協商書面通知提出對應方案，並進行協商。"},{"i":4,"t":"三、拒絕提供進行協商所必要之資料。"},{"i":0,"t":"依前項所定有協商資格之勞方，指下列工會："},{"i":4,"t":"一、企業工會。"},{"i":4,"t":"二、會員受僱於協商他方之人數，逾其所僱用勞工人數二分之一之產業工會。"},{"i":4,"t":"三、會員受僱於協商他方之人數，逾其所僱用具同類職業技能勞工人數二分之一之職業工會或綜合性工會。"},{"i":4,"t":"四、不符合前三款規定之數工會，所屬會員受僱於協商他方之人數合計逾其所僱用勞工人數二分之一。"},{"i":4,"t":"五、經依勞資爭議處理法規定裁決認定之工會。"},{"i":0,"t":"勞方有二個以上之工會，或資方有二個以上之雇主或雇主團體提出團體協約之協商時，他方得要求推選協商代表；無法產生協商代表時，依會員人數比例分配產生。"},{"i":0,"t":"勞資雙方進行團體協約之協商期間逾六個月，並經勞資爭議處理法之裁決認定有違反第一項、第二項第一款或第二款規定之無正當理由拒絕協商者，直轄市或縣（市）主管機關於考量勞資雙方當事人利益及簽訂團體協約之可能性後，得依職權交付仲裁。但勞資雙方另有約定者，不在此限。"}]},{"no":"7","ch":"第 二 章 團體協約之協商及簽訂","lines":[{"i":0,"t":"因進行團體協約之協商而提供資料之勞資一方，得要求他方保守秘密，並給付必要費用。"}]},{"no":"8","ch":"第 二 章 團體協約之協商及簽訂","lines":[{"i":0,"t":"工會或雇主團體以其團體名義進行團體協約之協商時，其協商代表應依下列方式之一產生："},{"i":4,"t":"一、依其團體章程之規定。"},{"i":4,"t":"二、依其會員大會或會員代表大會之決議。"},{"i":4,"t":"三、經通知其全體會員，並由過半數會員以書面委任。"},{"i":0,"t":"前項協商代表，以工會或雇主團體之會員為限。但經他方書面同意者，不在此限。"},{"i":0,"t":"第一項協商代表之人數，以該團體協約之協商所必要者為限。"}]},{"no":"9","ch":"第 二 章 團體協約之協商及簽訂","lines":[{"i":0,"t":"工會或雇主團體以其團體名義簽訂團體協約，除依其團體章程之規定為之者外，應先經其會員大會或會員代表大會之會員或會員代表過半數出席，出席會員或會員代表三分之二以上之決議，或通知其全體會員，經四分之三以上會員以書面同意。"},{"i":0,"t":"未依前項規定所簽訂之團體協約，於補行前項程序追認前，不生效力。"}]},{"no":"10","ch":"第 二 章 團體協約之協商及簽訂","lines":[{"i":0,"t":"團體協約簽訂後，勞方當事人應將團體協約送其主管機關備查；其變更或終止時，亦同。"},{"i":0,"t":"下列團體協約，應於簽訂前取得核可，未經核可者，無效："},{"i":4,"t":"一、一方當事人為公營事業機構者，應經其主管機關核可。"},{"i":4,"t":"二、一方當事人為國防部所屬機關（構）、學校者，應經國防部核可。"},{"i":4,"t":"三、一方當事人為前二款以外之政府機關（構）、公立學校而有上級主管機關者，應經其上級主管機關核可。但關係人為工友（含技工、駕駛）者，應經行政院人事行政局核可。"}]},{"no":"11","ch":"第 二 章 團體協約之協商及簽訂","lines":[{"i":0,"t":"團體協約雙方當事人應將團體協約公開揭示之，並備置一份供團體協約關係人隨時查閱。"}]},{"no":"12","ch":"第 三 章 團體協約之內容及限制","lines":[{"i":0,"t":"團體協約得約定下列事項："},{"i":4,"t":"一、工資、工時、津貼、獎金、調動、資遣、退休、職業災害補償、撫卹等勞動條件。"},{"i":4,"t":"二、企業內勞動組織之設立與利用、就業服務機構之利用、勞資爭議調解、仲裁機構之設立及利用。"},{"i":4,"t":"三、團體協約之協商程序、協商資料之提供、團體協約之適用範圍、有效期間及和諧履行協約義務。"},{"i":4,"t":"四、工會之組織、運作、活動及企業設施之利用。"},{"i":4,"t":"五、參與企業經營與勞資合作組織之設置及利用。"},{"i":4,"t":"六、申訴制度、促進勞資合作、升遷、獎懲、教育訓練、安全衛生、企業福利及其他關於勞資共同遵守之事項。"},{"i":4,"t":"七、其他當事人間合意之事項。"},{"i":0,"t":"學徒關係與技術生、養成工、見習生、建教合作班之學生及其他與技術生性質相類之人，其前項各款事項，亦得於團體協約中約定。"}]},{"no":"13","ch":"第 三 章 團體協約之內容及限制","lines":[{"i":0,"t":"團體協約得約定，受該團體協約拘束之雇主，非有正當理由，不得對所屬非該團體協約關係人之勞工，就該團體協約所約定之勞動條件，進行調整。但團體協約另有約定，非該團體協約關係人之勞工，支付一定之費用予工會者，不在此限。"}]},{"no":"14","ch":"第 三 章 團體協約之內容及限制","lines":[{"i":0,"t":"團體協約得約定雇主僱用勞工，以一定工會之會員為限。但有下列情形之一者，不在此限："},{"i":4,"t":"一、該工會解散。"},{"i":4,"t":"二、該工會無雇主所需之專門技術勞工。"},{"i":4,"t":"三、該工會之會員不願受僱，或其人數不足供給雇主所需僱用量。"},{"i":4,"t":"四、雇主招收學徒或技術生、養成工、見習生、建教合作班之學生及其他與技術生性質相類之人。"},{"i":4,"t":"五、雇主僱用為其管理財務、印信或機要事務之人。"},{"i":4,"t":"六、雇主僱用工會會員以外之勞工，扣除前二款人數，尚未超過其僱用勞工人數十分之二。"}]},{"no":"15","ch":"第 三 章 團體協約之內容及限制","lines":[{"i":0,"t":"團體協約不得有限制雇主採用新式機器、改良生產、買入製成品或加工品之約定。"}]},{"no":"16","ch":"第 三 章 團體協約之內容及限制","lines":[{"i":0,"t":"團體協約當事人之一方或雙方為多數時，當事人不得再各自為異於團體協約之約定。但團體協約另有約定者，從其約定。"}]},{"no":"17","ch":"第 四 章 團體協約之效力","lines":[{"i":0,"t":"團體協約除另有約定者外，下列各款之雇主及勞工均為團體協約關係人，應遵守團體協約所約定之勞動條件："},{"i":4,"t":"一、為團體協約當事人之雇主。"},{"i":4,"t":"二、屬於團體協約當事團體之雇主及勞工。"},{"i":4,"t":"三、團體協約簽訂後，加入團體協約當事團體之雇主及勞工。"},{"i":0,"t":"前項第三款之團體協約關係人，其關於勞動條件之規定，除該團體協約另有約定外，自取得團體協約關係人資格之日起適用之。"}]},{"no":"18","ch":"第 四 章 團體協約之效力","lines":[{"i":0,"t":"前條第一項所列團體協約關係人因團體協約所生之權利義務關係，除第二十一條規定者外，於該團體協約終止時消滅。"},{"i":0,"t":"團體協約簽訂後，自團體協約當事團體退出之雇主或勞工，於該團體協約有效期間內，仍應繼續享有及履行其因團體協約所生之權利義務關係。"}]},{"no":"19","ch":"第 四 章 團體協約之效力","lines":[{"i":0,"t":"團體協約所約定勞動條件，當然為該團體協約所屬雇主及勞工間勞動契約之內容。勞動契約異於該團體協約所約定之勞動條件者，其相異部分無效；無效之部分以團體協約之約定代之。但異於團體協約之約定，為該團體協約所容許或為勞工之利益變更勞動條件，而該團體協約並未禁止者，仍為有效。"}]},{"no":"20","ch":"第 四 章 團體協約之效力","lines":[{"i":0,"t":"團體協約有約定第十二條第一項第一款及第二款以外之事項者，對於其事項不生前三條之效力。"},{"i":0,"t":"團體協約關係人違反團體協約中不屬於第十二條第一項第一款之約定時，除團體協約另有約定者外，適用民法之規定。"}]},{"no":"21","ch":"第 四 章 團體協約之效力","lines":[{"i":0,"t":"團體協約期間屆滿，新團體協約尚未簽訂時，於勞動契約另為約定前，原團體協約關於勞動條件之約定，仍繼續為該團體協約關係人間勞動契約之內容。"}]},{"no":"22","ch":"第 四 章 團體協約之效力","lines":[{"i":0,"t":"團體協約關係人，如於其勞動契約存續期間拋棄其由團體協約所得勞動契約上之權利，其拋棄無效。但於勞動契約終止後三個月內仍不行使其權利者，不得再行使。"},{"i":0,"t":"受團體協約拘束之雇主，因勞工主張其於團體協約所享有之權利或勞動契約中基於團體協約所生之權利，而終止勞動契約者，其終止為無效。"}]},{"no":"23","ch":"第 四 章 團體協約之效力","lines":[{"i":0,"t":"團體協約當事人及其權利繼受人，不得以妨害團體協約之存在或其各個約定之存在為目的，而為爭議行為。"},{"i":0,"t":"團體協約當事團體，對於所屬會員，有使其不為前項爭議行為及不違反團體協約約定之義務。"},{"i":0,"t":"團體協約得約定當事人之一方不履行團體協約所約定義務或違反前二項規定時，對於他方應給付違約金。"},{"i":0,"t":"關於團體協約之履行，除本法另有規定外，適用民法之規定。"}]},{"no":"24","ch":"第 四 章 團體協約之效力","lines":[{"i":0,"t":"團體協約當事團體，對於違反團體協約之約定者，無論其為團體或個人為本團體之會員或他方團體之會員，均得以團體名義，請求損害賠償。"}]},{"no":"25","ch":"第 四 章 團體協約之效力","lines":[{"i":0,"t":"團體協約當事團體，得以團體名義，為其會員提出有關協約之一切訴訟。但應先通知會員，並不得違反其明示之意思。"},{"i":0,"t":"關於團體協約之訴訟，團體協約當事團體於其會員為被告時，得為參加。"}]},{"no":"26","ch":"第 五 章 團體協約之存續期間","lines":[{"i":0,"t":"團體協約得以定期、不定期或完成一定工作為期限，簽訂之。"}]},{"no":"27","ch":"第 五 章 團體協約之存續期間","lines":[{"i":0,"t":"團體協約為不定期者，當事人之一方於團體協約簽訂一年後，得隨時終止團體協約。但應於三個月前，以書面通知他方當事人。"},{"i":0,"t":"團體協約約定之通知期間較前項但書規定之期間為長者，從其約定。"}]},{"no":"28","ch":"第 五 章 團體協約之存續期間","lines":[{"i":0,"t":"團體協約為定期者，其期限不得超過三年；超過三年者，縮短為三年。"}]},{"no":"29","ch":"第 五 章 團體協約之存續期間","lines":[{"i":0,"t":"團體協約以完成一定工作為期限者，其工作於三年內尚未完成時，視為以三年為期限簽訂之團體協約。"}]},{"no":"30","ch":"第 五 章 團體協約之存續期間","lines":[{"i":0,"t":"團體協約當事人及當事團體之權利義務，除團體協約另有約定外，因團體之合併或分立，移轉於因合併或分立而成立之團體。"},{"i":0,"t":"團體協約當事團體解散時，其團體所屬會員之權利義務，不因其團體之解散而變更。但不定期之團體協約於該團體解散後，除團體協約另有約定外，經過三個月消滅。"}]},{"no":"31","ch":"第 五 章 團體協約之存續期間","lines":[{"i":0,"t":"團體協約簽訂後經濟情形有重大變化，如維持該團體協約有與雇主事業之進行或勞工生活水準之維持不相容，或因團體協約當事人之行為，致有無法達到協約目的之虞時，當事人之一方得向他方請求協商變更團體協約內容或終止團體協約。"}]},{"no":"32","ch":"第 六 章 罰則","lines":[{"i":0,"t":"勞資之一方，違反第六條第一項規定，經依勞資爭議處理法之裁決認定者，處新臺幣十萬元以上五十萬元以下罰鍰。"},{"i":0,"t":"勞資之一方，未依前項裁決決定書所定期限為一定行為或不行為者，再處新臺幣十萬元以上五十萬元以下罰鍰，並得令其限期改正；屆期仍未改正者，得按次連續處罰。"}]},{"no":"33","ch":"第 七 章 附則","lines":[{"i":0,"t":"本法施行前已簽訂之團體協約，自本法修正施行之日起，除第十條第二項規定外，適用修正後之規定。"}]},{"no":"34","ch":"第 七 章 附則","lines":[{"i":0,"t":"本法施行日期，由行政院定之。"}]}],"amendments":[{"date":"19301028","roc":"19.10.28","desc":"中華民國十九年十月二十八日國民政府制定公布全文 31 條；並自二十一年十一月一日施行","title":"制定公布全文 31 條","changes":[]},{"date":"20080109","roc":"97.01.09","desc":"中華民國九十七年一月九日總統華總一義字第 09700000831 號令修正公布全文 34 條；施行日期，由行政院定之\n中華民國一百年四月二十六日行政院院臺勞字第 1000019757 號令發布定自一百年五月一日施行\n中華民國一百零一年二月三日行政院院臺規字第 1010122318 號公告第 10 條第 2 項第 3 款所列屬「行政院人事行政局」之權責事項，自一百零一年二月六日起改由「行政院人事行政總處」管轄\n中華民國一百零三年二月十四日行政院院臺規字第 1030124618 號公告第 5 條所列屬「行政院勞工委員會」之權責事項，自一百零三年二月十七日起改由「勞動部」管轄","title":"修正公布全文 34 條（100.05.01 施行）","changes":[{"no":"1","type":"add","old":[],"new":[{"i":0,"t":"為規範團體協約之協商程序及其效力，穩定勞動關係，促進勞資和諧，保障勞資權益，特制定本法。"}]},{"no":"2","type":"mod","old":[{"i":0,"t":"稱團體協約者，謂僱主或有法人資格之僱主團體，與有法人資格之工人團體，以規定勞動關係為目的所締結之書面契約。左列各款亦屬本法所稱勞動關係："},{"i":4,"t":"一、學徒關係。"},{"i":4,"t":"二、企業內之勞動組織。"},{"i":4,"t":"三、關於職業介紹機關之利用。"},{"i":4,"t":"四、關於勞資糾紛調解機關或仲裁機關之設立或利用。"}],"new":[{"i":0,"t":"本法所稱團體協約，指雇主或有法人資格之雇主團體，與依工會法成立之工會，以約定勞動關係及相關事項為目的所簽訂之書面契約。"}],"oldNos":["1"]},{"no":"3","type":"add","old":[],"new":[{"i":0,"t":"團體協約違反法律強制或禁止之規定者，無效。但其規定並不以之為無效者，不在此限。"}]},{"no":"4","type":"mod","old":[{"i":0,"t":"勞動關係於有二個以上之團體協約可以適用時，其效力發生在前之團體協約無特別規定者，先適用職業範圍較小之團體協約。團體協約不屬於職業性質者，先適用地域或人數適用範圍較大之團體協約。"}],"new":[{"i":0,"t":"有二個以上之團體協約可適用時，除效力發生在前之團體協約有特別約定者外，優先適用職業範圍較為狹小或職務種類較為特殊之團體協約；團體協約非以職業或職務為規範者，優先適用地域或人數適用範圍較大之團體協約。"}],"oldNos":["5"]},{"no":"5","type":"add","old":[],"new":[{"i":0,"t":"本法所稱主管機關：在中央為行政院勞工委員會；在直轄市為直轄市政府；在縣（市）為縣（市）政府。"}]},{"no":"6","type":"add","old":[],"new":[{"i":0,"t":"勞資雙方應本誠實信用原則，進行團體協約之協商；對於他方所提團體協約之協商，無正當理由者，不得拒絕。"},{"i":0,"t":"勞資之一方於有協商資格之他方提出協商時，有下列情形之一，為無正當理由："},{"i":4,"t":"一、對於他方提出合理適當之協商內容、時間、地點及進行方式，拒絕進行協商。"},{"i":4,"t":"二、未於六十日內針對協商書面通知提出對應方案，並進行協商。"},{"i":4,"t":"三、拒絕提供進行協商所必要之資料。"},{"i":0,"t":"依前項所定有協商資格之勞方，指下列工會："},{"i":4,"t":"一、企業工會。"},{"i":4,"t":"二、會員受僱於協商他方之人數，逾其所僱用勞工人數二分之一之產業工會。"},{"i":4,"t":"三、會員受僱於協商他方之人數，逾其所僱用具同類職業技能勞工人數二分之一之職業工會或綜合性工會。"},{"i":4,"t":"四、不符合前三款規定之數工會，所屬會員受僱於協商他方之人數合計逾其所僱用勞工人數二分之一。"},{"i":4,"t":"五、經依勞資爭議處理法規定裁決認定之工會。"},{"i":0,"t":"勞方有二個以上之工會，或資方有二個以上之雇主或雇主團體提出團體協約之協商時，他方得要求推選協商代表；無法產生協商代表時，依會員人數比例分配產生。"}]},{"no":"7","type":"add","old":[],"new":[{"i":0,"t":"因進行團體協約之協商而提供資料之勞資一方，得要求他方保守秘密，並給付必要費用。"}]},{"no":"8","type":"mod","old":[{"i":0,"t":"勞資團體之代表機關，非依其團體章程之規定、或依其團員大會或代表大會之決議、或受其團體全團團員各個所授與特別書面之委任，不得以其團體之名義締結團體協約。"},{"i":0,"t":"違反前項規定所締結之團體協約，非得其團員大會之追認不發生效力。"}],"new":[{"i":0,"t":"工會或雇主團體以其團體名義進行團體協約之協商時，其協商代表應依下列方式之一產生："},{"i":4,"t":"一、依其團體章程之規定。"},{"i":4,"t":"二、依其會員大會或會員代表大會之決議。"},{"i":4,"t":"三、經通知其全體會員，並由過半數會員以書面委任。"},{"i":0,"t":"前項協商代表，以工會或雇主團體之會員為限。但經他方書面同意者，不在此限。"},{"i":0,"t":"第一項協商代表之人數，以該團體協約之協商所必要者為限。"}],"oldNos":["3"]},{"no":"9","type":"mod","old":[{"i":0,"t":"勞資團體之代表機關，非依其團體章程之規定、或依其團員大會或代表大會之決議、或受其團體全團團員各個所授與特別書面之委任，不得以其團體之名義締結團體協約。"},{"i":0,"t":"違反前項規定所締結之團體協約，非得其團員大會之追認不發生效力。"}],"new":[{"i":0,"t":"工會或雇主團體以其團體名義簽訂團體協約，除依其團體章程之規定為之者外，應先經其會員大會或會員代表大會之會員或會員代表過半數出席，出席會員或會員代表三分之二以上之決議，或通知其全體會員，經四分之三以上會員以書面同意。"},{"i":0,"t":"未依前項規定所簽訂之團體協約，於補行前項程序追認前，不生效力。"}],"oldNos":["3"]},{"no":"10","type":"mod","old":[{"i":0,"t":"團體協約應由當事人雙方或一方呈請主管官署認可。主管官署發現團體協約條款中有違背法令、或與僱主事業之進行不相容、或與工人從來生活標準之維持不相容者，應刪除或修改之。如得當事人同意時，得就其刪除或修改後之團體協約認可。已認可之團體協約自認可之翌日起發生效力。"},{"i":0,"t":"前項之規定於團體協約之變更或廢止準用之。"}],"new":[{"i":0,"t":"團體協約簽訂後，勞方當事人應將團體協約送其主管機關備查；其變更或終止時，亦同。"},{"i":0,"t":"下列團體協約，應於簽訂前取得核可，未經核可者，無效："},{"i":4,"t":"一、一方當事人為公營事業機構者，應經其主管機關核可。"},{"i":4,"t":"二、一方當事人為國防部所屬機關（構）、學校者，應經國防部核可。"},{"i":4,"t":"三、一方當事人為前二款以外之政府機關（構）、公立學校而有上級主管機關者，應經其上級主管機關核可。但關係人為工友（含技工、駕駛）者，應經行政院人事行政局核可。"}],"oldNos":["4"]},{"no":"11","type":"mod","old":[{"i":0,"t":"僱主受團體協約之拘束者，應將團體協約於工作場所易見之處揭示之。違反前項規定者得處以五十元以下之罰鍰。"}],"new":[{"i":0,"t":"團體協約雙方當事人應將團體協約公開揭示之，並備置一份供團體協約關係人隨時查閱。"}],"oldNos":["7"]},{"no":"12","type":"mod","old":[{"i":0,"t":"稱團體協約者，謂僱主或有法人資格之僱主團體，與有法人資格之工人團體，以規定勞動關係為目的所締結之書面契約。左列各款亦屬本法所稱勞動關係："},{"i":4,"t":"一、學徒關係。"},{"i":4,"t":"二、企業內之勞動組織。"},{"i":4,"t":"三、關於職業介紹機關之利用。"},{"i":4,"t":"四、關於勞資糾紛調解機關或仲裁機關之設立或利用。"}],"new":[{"i":0,"t":"團體協約得約定下列事項："},{"i":4,"t":"一、工資、工時、津貼、獎金、調動、資遣、退休、職業災害補償、撫卹等勞動條件。"},{"i":4,"t":"二、企業內勞動組織之設立與利用、就業服務機構之利用、勞資爭議調解、仲裁機構之設立及利用。"},{"i":4,"t":"三、團體協約之協商程序、協商資料之提供、團體協約之適用範圍、有效期間及和諧履行協約義務。"},{"i":4,"t":"四、工會之組織、運作、活動及企業設施之利用。"},{"i":4,"t":"五、參與企業經營與勞資合作組織之設置及利用。"},{"i":4,"t":"六、申訴制度、促進勞資合作、升遷、獎懲、教育訓練、安全衛生、企業福利及其他關於勞資共同遵守之事項。"},{"i":4,"t":"七、其他當事人間合意之事項。"},{"i":0,"t":"學徒關係與技術生、養成工、見習生、建教合作班之學生及其他與技術生性質相類之人，其前項各款事項，亦得於團體協約中約定。"}],"oldNos":["1"]},{"no":"13","type":"add","old":[],"new":[{"i":0,"t":"團體協約得約定，受該團體協約拘束之雇主，非有正當理由，不得對所屬非該團體協約關係人之勞工，就該團體協約所約定之勞動條件，進行調整。但團體協約另有約定，非該團體協約關係人之勞工，支付一定之費用予工會者，不在此限。"}]},{"no":"14","type":"mod","old":[{"i":0,"t":"團體協約得規定僱用工人限於一定工人團體之團員，但有左列情形之一時僱主不受限制："},{"i":4,"t":"一、該工人團體解散時。"},{"i":4,"t":"二、該工人團體無僱主所需要之專門技術工人時。"},{"i":4,"t":"三、該工人之團體之團員不足供給或不願意應僱時。"},{"i":4,"t":"四、僱主僱用學徒或使役時。"},{"i":4,"t":"五、僱主僱用為其管理財務、印信、或機要文件者時。"},{"i":4,"t":"六、僱主僱用該工人團體以外之工人，除四、五兩款不計外尚未超過其廠店工人人數十分之二時。"}],"new":[{"i":0,"t":"團體協約得約定雇主僱用勞工，以一定工會之會員為限。但有下列情形之一者，不在此限："},{"i":4,"t":"一、該工會解散。"},{"i":4,"t":"二、該工會無雇主所需之專門技術勞工。"},{"i":4,"t":"三、該工會之會員不願受僱，或其人數不足供給雇主所需僱用量。"},{"i":4,"t":"四、雇主招收學徒或技術生、養成工、見習生、建教合作班之學生及其他與技術生性質相類之人。"},{"i":4,"t":"五、雇主僱用為其管理財務、印信或機要事務之人。"},{"i":4,"t":"六、雇主僱用工會會員以外之勞工，扣除前二款人數，尚未超過其僱用勞工人數十分之二。"}],"oldNos":["8"]},{"no":"15","type":"mod","old":[{"i":0,"t":"團體協約有限制僱主採用新式機器或改良生產，或限制僱主買入製成品或加工品之規定者，其規定為無效。"}],"new":[{"i":0,"t":"團體協約不得有限制雇主採用新式機器、改良生產、買入製成品或加工品之約定。"}],"oldNos":["13"]},{"no":"16","type":"mod","old":[{"i":0,"t":"資方之團體協約當事人為多數時，如無特別之規定，其各當事人不得單獨與一般工人團體為異於團體協約之特別規定。"},{"i":0,"t":"團體協約當事人除前項規定外，各自獨立取得權利、負擔義務。"}],"new":[{"i":0,"t":"團體協約當事人之一方或雙方為多數時，當事人不得再各自為異於團體協約之約定。但團體協約另有約定者，從其約定。"}],"oldNos":["6"]},{"no":"17","type":"mod","old":[{"i":0,"t":"團體協約如無特別限制,左列各款之僱主及工人均為團體協約關係人,應遵守團體協約所定之勞動條件："},{"i":4,"t":"一、為團體協約當事人之僱主。"},{"i":4,"t":"二、屬於團體協約當事團體之僱主及工人，或團體協約訂立或訂立後加該團體之僱主及工人。"},{"i":0,"t":"對於團體協約訂立後始為協約關係人者，除該團體協約另有規定外，其關於勞動條件之規定自取得團體協約關係人資格之日起適用之。"}],"new":[{"i":0,"t":"團體協約除另有約定者外，下列各款之雇主及勞工均為團體協約關係人，應遵守團體協約所約定之勞動條件："},{"i":4,"t":"一、為團體協約當事人之雇主。"},{"i":4,"t":"二、屬於團體協約當事團體之雇主及勞工。"},{"i":4,"t":"三、團體協約簽訂後，加入團體協約當事團體之雇主及勞工。"},{"i":0,"t":"前項第三款之團體協約關係人，其關於勞動條件之規定，除該團體協約另有約定外，自取得團體協約關係人資格之日起適用之。"}],"oldNos":["14"]},{"no":"18","type":"mod","old":[{"i":0,"t":"前條第一項各款所列團體協約關係人之所屬關係人之團體協約終止時終了。團體協約訂立後由協約當事團體退出之僱主或工人之所屬關係亦同。"}],"new":[{"i":0,"t":"前條第一項所列團體協約關係人因團體協約所生之權利義務關係，除第二十一條規定者外，於該團體協約終止時消滅。"},{"i":0,"t":"團體協約簽訂後，自團體協約當事團體退出之雇主或勞工，於該團體協約有效期間內，仍應繼續享有及履行其因團體協約所生之權利義務關係。"}],"oldNos":["15"]},{"no":"19","type":"mod","old":[{"i":0,"t":"團體協約所定勞動條件當然為該團體協約所屬僱主及工人間所訂勞動契約之內容。如勞動契約有異於該團體協約所定之勞動條件者，其相異之部分無效；無效之部分以團體協約之規定代之，但異於團體協約之約定為該團體協約所容許、或為工人之利益變更勞動條件而該團體協約並無明文禁止者為有效。"}],"new":[{"i":0,"t":"團體協約所約定勞動條件，當然為該團體協約所屬雇主及勞工間勞動契約之內容。勞動契約異於該團體協約所約定之勞動條件者，其相異部分無效；無效之部分以團體協約之約定代之。但異於團體協約之約定，為該團體協約所容許或為勞工之利益變更勞動條件，而該團體協約並未禁止者，仍為有效。"}],"oldNos":["16"]},{"no":"20","type":"mod","old":[{"i":0,"t":"團體協約有規定勞動關係以外之事項者，對於其事項不適用本法之規定。"},{"i":0,"t":"團體協約關係人違反團體協約中不屬於勞動條件之規定時，除該團體協約另有規定外，法院依利害關係之僱主或團體協約當事人之聲請，得科僱主五百元以下、工人五十元以下之罰金。前項罰金應使用於為工人之福利事業。"}],"new":[{"i":0,"t":"團體協約有約定第十二條第一項第一款及第二款以外之事項者，對於其事項不生前三條之效力。"},{"i":0,"t":"團體協約關係人違反團體協約中不屬於第十二條第一項第一款之約定時，除團體協約另有約定者外，適用民法之規定。"}],"oldNos":["2","19"]},{"no":"21","type":"mod","old":[{"i":0,"t":"團體協約已屆期滿，新團體協約尚未訂立時，於勞動契約另為約定前，原團體協約關於勞動條件之規定，仍繼續為該團體協約關係人之勞動契約之內容。"}],"new":[{"i":0,"t":"團體協約期間屆滿，新團體協約尚未簽訂時，於勞動契約另為約定前，原團體協約關於勞動條件之約定，仍繼續為該團體協約關係人間勞動契約之內容。"}],"oldNos":["17"]},{"no":"22","type":"mod","old":[{"i":0,"t":"團體協約關係人如於其勞動契約存續期間拋棄其由團體協約所得勞動契約上之權利，其拋棄為無效；但於勞動契約終了後三個月內仍不行使其權利者不得復行使之。團體協約所屬之僱主，因工人維持其於團體協約所生之權利，或基於團體協約所生之權利而終止勞動契約者，其終止為無效。"}],"new":[{"i":0,"t":"團體協約關係人，如於其勞動契約存續期間拋棄其由團體協約所得勞動契約上之權利，其拋棄無效。但於勞動契約終止後三個月內仍不行使其權利者，不得再行使。"},{"i":0,"t":"受團體協約拘束之雇主，因勞工主張其於團體協約所享有之權利或勞動契約中基於團體協約所生之權利，而終止勞動契約者，其終止為無效。"}],"oldNos":["18"]},{"no":"23","type":"mod","old":[{"i":0,"t":"團體協約當事人及其權利承繼人，對於妨害團體協約之存在，或其各個規定之存在之一切鬥爭手段不得採用。團體協約當事團體，對於其所屬團員，有使其不為前項鬥爭，並使其不違反團體協約之規定之義務。"},{"i":0,"t":"團體協約得約定當事人一方不履團體協約所定之義務時，對於他方應給代替損害賠償之一定償金。關於團體協約之履行，除本法有特別規定外，適用民法之規定。"}],"new":[{"i":0,"t":"團體協約當事人及其權利繼受人，不得以妨害團體協約之存在或其各個約定之存在為目的，而為爭議行為。"},{"i":0,"t":"團體協約當事團體，對於所屬會員，有使其不為前項爭議行為及不違反團體協約約定之義務。"},{"i":0,"t":"團體協約得約定當事人之一方不履行團體協約所約定義務或違反前二項規定時，對於他方應給付違約金。"},{"i":0,"t":"關於團體協約之履行，除本法另有規定外，適用民法之規定。"}],"oldNos":["20"]},{"no":"24","type":"mod","old":[{"i":0,"t":"團體協約當事團體對於違反團體協約之規定者，無論其為團體或個人，為本團體之團員，或他團體之團員，均得以團體名義請求損害賠償。"}],"new":[{"i":0,"t":"團體協約當事團體，對於違反團體協約之約定者，無論其為團體或個人為本團體之會員或他方團體之會員，均得以團體名義，請求損害賠償。"}],"oldNos":["21"]},{"no":"25","type":"mod","old":[{"i":0,"t":"團體協約當事團體，無須特別之委任，得為其團員提出團體協約上一切之訴訟；但以先通知本人而本人不表示反對時為限。"},{"i":0,"t":"關於團體協約上之訴訟，團體協約當事團體之團員為被告人時，團體亦得隨時參加訴訟。"}],"new":[{"i":0,"t":"團體協約當事團體，得以團體名義，為其會員提出有關協約之一切訴訟。但應先通知會員，並不得違反其明示之意思。"},{"i":0,"t":"關於團體協約之訴訟，團體協約當事團體於其會員為被告時，得為參加。"}],"oldNos":["22"]},{"no":"26","type":"mod","old":[{"i":0,"t":"團體協約得以定期、不定期、或一定之工作為期訂立之。"}],"new":[{"i":0,"t":"團體協約得以定期、不定期或完成一定工作為期限，簽訂之。"}],"oldNos":["23"]},{"no":"27","type":"mod","old":[{"i":0,"t":"團體協約不定期者，其當事人之一方於團體協約訂立一年後得隨時終止團體協約；但應於三個月前以書面通知他方當事人。"},{"i":0,"t":"團體協約所規定之通知期間較前項規定期間為長者，依其規定。"}],"new":[{"i":0,"t":"團體協約為不定期者，當事人之一方於團體協約簽訂一年後，得隨時終止團體協約。但應於三個月前，以書面通知他方當事人。"},{"i":0,"t":"團體協約約定之通知期間較前項但書規定之期間為長者，從其約定。"}],"oldNos":["24"]},{"no":"28","type":"mod","old":[{"i":0,"t":"團體協約為定期者，其期限不得超過三年；超過三年者視為三年。"}],"new":[{"i":0,"t":"團體協約為定期者，其期限不得超過三年；超過三年者，縮短為三年。"}],"oldNos":["25"]},{"no":"29","type":"mod","old":[{"i":0,"t":"團體協約以一年工作之完成為期限者，其工作於三年內尚未完成時，視為以三年期限訂立之團體協約。"}],"new":[{"i":0,"t":"團體協約以完成一定工作為期限者，其工作於三年內尚未完成時，視為以三年為期限簽訂之團體協約。"}],"oldNos":["26"]},{"no":"30","type":"mod","old":[{"i":0,"t":"團體協約當事團體在團體協約上之權利義務，除團體協約當事人另有約定外，因團體之合併或分立移轉於因合併或分立而成立之團體。"},{"i":0,"t":"團體協約當事團體解散時，其團體所屬各員在團體協約上之權利義務不因其團體之解散而變更其效力；但不定期之團體協約於解散後經過通知期間失效力。"}],"new":[{"i":0,"t":"團體協約當事人及當事團體之權利義務，除團體協約另有約定外，因團體之合併或分立，移轉於因合併或分立而成立之團體。"},{"i":0,"t":"團體協約當事團體解散時，其團體所屬會員之權利義務，不因其團體之解散而變更。但不定期之團體協約於該團體解散後，除團體協約另有約定外，經過三個月消滅。"}],"oldNos":["27"]},{"no":"31","type":"mod","old":[{"i":0,"t":"團體協約訂立時之經濟情形於訂立後有重大變更，如維持該團體協約有與僱主事業之進行或與原來工人生活標準之維持不相容，或依團體協約當事人之行為致無達到當初目的之希望時，主管官署因團體協約當事人一方之聲請得廢止團體協約。"}],"new":[{"i":0,"t":"團體協約簽訂後經濟情形有重大變化，如維持該團體協約有與雇主事業之進行或勞工生活水準之維持不相容，或因團體協約當事人之行為，致有無法達到協約目的之虞時，當事人之一方得向他方請求協商變更團體協約內容或終止團體協約。"}],"oldNos":["28"]},{"no":"32","type":"add","old":[],"new":[{"i":0,"t":"勞資之一方，違反第六條第一項規定，經依勞資爭議處理法之裁決認定者，處新臺幣十萬元以上五十萬元以下罰鍰。"},{"i":0,"t":"勞資之一方，未依前項裁決決定書所定期限為一定行為或不行為者，再處新臺幣十萬元以上五十萬元以下罰鍰，並得令其限期改正；屆期仍未改正者，得按次連續處罰。"}]},{"no":"33","type":"mod","old":[{"i":0,"t":"團體協約在本法施行前訂立者，自本法施行之日起適用本法。"}],"new":[{"i":0,"t":"本法施行前已簽訂之團體協約，自本法修正施行之日起，除第十條第二項規定外，適用修正後之規定。"}],"oldNos":["30"]},{"no":"34","type":"mod","old":[{"i":0,"t":"本法施行日期以命令定之。"}],"new":[{"i":0,"t":"本法施行日期，由行政院定之。"}],"oldNos":["31"]},{"no":null,"oldNos":["9"],"type":"del","old":[{"i":0,"t":"團體協約有規定僱主僱用工人應依工人團體所定輪僱工人表之次序者，其規定為無效。"}],"new":[]},{"no":null,"oldNos":["10"],"type":"del","old":[{"i":0,"t":"團體協約得規定僱主僱用工人應由工人團體介紹，但限制僱主之自由去取者其規定為無效。如規定工人團體有介紹權時，應規定由接到僱主通知之日起一星期內之一定期間尚未介紹工人到工時，僱主得僱用工人團體以外之工人。"}],"new":[]},{"no":null,"oldNos":["11"],"type":"del","old":[{"i":0,"t":"團體協約得規定僱主於休假日或於原定之工作時間外必須工人工作或繼續工作時，其工資應加成或加倍發給；但不得超過二倍，超過二倍者視為二倍。"}],"new":[]},{"no":null,"oldNos":["12"],"type":"del","old":[{"i":0,"t":"團體協約規定工人團體現任職員因辦理會務復請假之時間，但至多每月平均不得超過三十小時。"}],"new":[]},{"no":null,"oldNos":["29"],"type":"del","old":[{"i":0,"t":"團體協約之廢止，縱有反對之約定，仍對於該團體團員全體發生效力。"}],"new":[]}],"full":true,"note":"本次為全文修正（31 條→34 條），條次全部重新編排。下列「原第○條」係依條文內容所作之新舊條次對應，僅供比較參考；未列對應者為新增條文。"},{"date":"20140604","roc":"103.06.04","desc":"中華民國一百零三年六月四日總統華總一義字第 10300085171 號令修正公布第 6 條條文；施行日期，由行政院定之\n中華民國一百零三年六月二十七日行政院院臺勞字第 1030037473 號令發布定自一百零三年七月一日施行","title":"修正第 6 條（增訂第 5 項）","changes":[{"no":"6","type":"mod","old":[{"i":0,"t":"勞資雙方應本誠實信用原則，進行團體協約之協商；對於他方所提團體協約之協商，無正當理由者，不得拒絕。"},{"i":0,"t":"勞資之一方於有協商資格之他方提出協商時，有下列情形之一，為無正當理由："},{"i":4,"t":"一、對於他方提出合理適當之協商內容、時間、地點及進行方式，拒絕進行協商。"},{"i":4,"t":"二、未於六十日內針對協商書面通知提出對應方案，並進行協商。"},{"i":4,"t":"三、拒絕提供進行協商所必要之資料。"},{"i":0,"t":"依前項所定有協商資格之勞方，指下列工會："},{"i":4,"t":"一、企業工會。"},{"i":4,"t":"二、會員受僱於協商他方之人數，逾其所僱用勞工人數二分之一之產業工會。"},{"i":4,"t":"三、會員受僱於協商他方之人數，逾其所僱用具同類職業技能勞工人數二分之一之職業工會或綜合性工會。"},{"i":4,"t":"四、不符合前三款規定之數工會，所屬會員受僱於協商他方之人數合計逾其所僱用勞工人數二分之一。"},{"i":4,"t":"五、經依勞資爭議處理法規定裁決認定之工會。"},{"i":0,"t":"勞方有二個以上之工會，或資方有二個以上之雇主或雇主團體提出團體協約之協商時，他方得要求推選協商代表；無法產生協商代表時，依會員人數比例分配產生。"}],"new":[{"i":0,"t":"勞資雙方應本誠實信用原則，進行團體協約之協商；對於他方所提團體協約之協商，無正當理由者，不得拒絕。"},{"i":0,"t":"勞資之一方於有協商資格之他方提出協商時，有下列情形之一，為無正當理由："},{"i":4,"t":"一、對於他方提出合理適當之協商內容、時間、地點及進行方式，拒絕進行協商。"},{"i":4,"t":"二、未於六十日內針對協商書面通知提出對應方案，並進行協商。"},{"i":4,"t":"三、拒絕提供進行協商所必要之資料。"},{"i":0,"t":"依前項所定有協商資格之勞方，指下列工會："},{"i":4,"t":"一、企業工會。"},{"i":4,"t":"二、會員受僱於協商他方之人數，逾其所僱用勞工人數二分之一之產業工會。"},{"i":4,"t":"三、會員受僱於協商他方之人數，逾其所僱用具同類職業技能勞工人數二分之一之職業工會或綜合性工會。"},{"i":4,"t":"四、不符合前三款規定之數工會，所屬會員受僱於協商他方之人數合計逾其所僱用勞工人數二分之一。"},{"i":4,"t":"五、經依勞資爭議處理法規定裁決認定之工會。"},{"i":0,"t":"勞方有二個以上之工會，或資方有二個以上之雇主或雇主團體提出團體協約之協商時，他方得要求推選協商代表；無法產生協商代表時，依會員人數比例分配產生。"},{"i":0,"t":"勞資雙方進行團體協約之協商期間逾六個月，並經勞資爭議處理法之裁決認定有違反第一項、第二項第一款或第二款規定之無正當理由拒絕協商者，直轄市或縣（市）主管機關於考量勞資雙方當事人利益及簽訂團體協約之可能性後，得依職權交付仲裁。但勞資雙方另有約定者，不在此限。"}]}]},{"date":"20150701","roc":"104.07.01","desc":"中華民國一百零四年七月一日總統華總一義字第 10400077131 號令修正公布第 5 條條文；施行日期，由行政院定之\n中華民國一百零四年十月五日行政院院臺勞字第 1040046667 號令發布定自一百零四年七月三日施行","title":"修正第 5 條","changes":[{"no":"5","type":"mod","old":[{"i":0,"t":"本法所稱主管機關：在中央為行政院勞工委員會；在直轄市為直轄市政府；在縣（市）為縣（市）政府。"}],"new":[{"i":0,"t":"本法所稱主管機關：在中央為勞動部；在直轄市為直轄市政府；在縣（市）為縣（市）政府。"}]}]}],"interps":[],"cases":[{"id":"C113上600","type":"S","title":"最高行政法院113年度上字第600號判決","date":"","topic":"誠信協商義務之範圍：限於與勞動條件相關、雇主有處理權限之事項","summary":"團體協約為資方即雇主或有法人資格之雇主團體，與勞方即依工會法成立之工會，以約定勞動關係及相關事項為目的所簽訂之書面契約（團體協約法第2條參照），旨在使勞動者得藉工會集體力量，在與雇主對立之協商過程，取得較平等之談判地位。依團體協約法第6條規定：「(第1項)勞資雙方應本誠實信用原則，進行團體協約之協商；對於他方所提團體協約之協商，無正當理由者，不得拒絕。(第2項)勞資之一方於有協商資格之他方提出協商時，有下列情形之一，為無正當理由：一、對於他方提出合理適當之協商內容、時間、地點及進行方式，拒絕進行協商。……。」勞資雙方均負有進行團體協約協商之義務，非有正當理由，不得任意拒絕，且以誠實信用原則為最高指導原則之一。而為維持勞資自治自律原則，並避免任一方無正當理由拒絕團體協約之協商，例如佯裝協商、拖延協商或刻意杯葛協商程序等，致協商無法進行，團體協約法第6條第2項並例示無正當理由拒絕協商之情事（團體協約法第6條立法理由參照）。惟勞資雙方所負誠信協商義務，應以與勞工之勞動條件相關者為限，若工會提出之協商內容與勞工之工作條件無關，復非雇主有處理權限之事項，即難謂合理正當，雇主並不負有協商義務；","arts":["2","6"],"src":"摘自本判決理由","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPAA%2c113%2c%e4%b8%8a%2c600%2c20260430%2c1&ot=in"},{"id":"C111上439","type":"S","title":"最高行政法院111年度上字第439號判決","date":"","topic":"誠信協商義務之意義；是否違反應依勞資關係脈絡、客觀情狀判斷","summary":"團體協約是為維持並改善勞動條件，確保並提升勞工之地位所發展而來，理論上是勞工為克服個人相對於雇主處於較弱的立場，透過團結的力量，進行團體協商所締結的成果。依團體協約法第6條第1項規定：「勞資雙方應本誠實信用原則，進行團體協約之協商；對於他方所提團體協約之協商，無正當理由者，不得拒絕。」團體協約為工會與雇主或雇主團體透過指派代表進行協商後，達成合意所簽訂之契約，旨在使勞動者得藉工會集體力量，在與雇主對立之協商過程，取得較平等之談判地位，是勞資雙方均有進行團體協約協商之義務，非有正當理由，不得任意拒絕，且以誠實信用原則為最高指導原則之一。為維持勞資自治自律原則，並避免任一方無正當理由拒絕團體協約之協商，例如佯裝協商、拖延協商或刻意杯葛協商程序等，致協商無法進行，團體協約法第6條第2項並例示無正當理由拒絕協商之情事（團體協約法第6條立法理由參照）。判斷雇主之行為是否已依誠實信用原則進行團體協約之協商，則應依勞資關係脈絡，就客觀事實之一切情狀為認定。","arts":["6"],"src":"摘自本判決理由","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPAA%2c111%2c%e4%b8%8a%2c439%2c20230921%2c1&ot=in"},{"id":"C111上439-1","type":"S","title":"最高行政法院111年度上字第439號判決","date":"","topic":"未依裁決決定所定期限協商，依第32條第2項再處罰，非一行為二罰","summary":"原處分認定上訴人違反團體協約法第32條第2項規定之事實，乃係指上訴人未履行系爭裁決主文第2項「應自收到決定書翌日起30日內與元大金控工會進行團體協商」之行為義務，而非上訴人所指系爭裁決主文第1項：「確認上訴人以108年4月19日函文拒絕與元大金控工會進行團體協商之行為，構成違反團體協約法第6條第1項之不當勞動行為」之行為所進行之重複評價，並無上訴人所稱違反一行為不兩罰之情事。","arts":["32"],"src":"摘自本判決理由","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPAA%2c111%2c%e4%b8%8a%2c439%2c20230921%2c1&ot=in"},{"id":"C107判125","type":"S","title":"最高行政法院107年度判字第125號判決","date":"","topic":"協約草案已達合意，臨簽約始以董事會不同意拒簽，違反誠信協商","summary":"上訴人對上開內容如認有抵觸或窒礙難行之處，本得於協商過程中提出，其於歷經14次協商會議方通過之協約草案即將簽約之際，以董事會不同意而拒絕簽約，即難謂合理、正當，而有違誠信原則。原裁決決定亦認上訴人之行為係屬「拒絕就已達成合意之團體協約條文簽訂團體協約及意圖延滯協商程序，構成違反團體協約法第6條第1項之不當勞動行為」，認事用法亦無不合。","arts":["6"],"src":"摘自本判決理由","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPAA%2c107%2c%e5%88%a4%2c125%2c20180315%2c1&ot=in"},{"id":"C105判134","type":"S","title":"最高行政法院105年度判字第134號判決","date":"","topic":"「提出協商」須由協商代表提出合理適當之內容、時間、地點及進行方式","summary":"可知工會若欲依團體協約法第6條第2項第1款及第8條規定提出協商時，應由其協商代表將合理適當之協商內容、時間、地點及進行方式向雇主提出，始得認為有協商之提出。","arts":["6","8"],"src":"摘自本判決理由","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPAA%2c105%2c%e5%88%a4%2c134%2c20160331%2c1&ot=in"},{"id":"C107判270","type":"S","title":"最高行政法院107年度判字第270號判決","date":"","topic":"非會員擔任協商代表（未經他方書面同意）違反第8條第2項","summary":"團體協約法第8條第2項明定：「前項協商代表，以工會或雇主團體之會員為限。但經他方書面同意者，不在此限。」依此規定，本件除經參加人書面同意外，上訴人之協商代表以上訴人之工會會員為限，惟查上訴人與參加人105年6月24日協商會議之協商代表，除上訴人之工會會員趙剛等5人外，尚有非工會會員之林佳瑋秘書長、毛振飛顧問、吳俊達律師及劉冠廷律師等4人，有上訴人與參加人之協商會議紀錄在卷可稽（原審卷第249頁至252頁），本件既未經參加人之書面同意，則上開非會員之林佳瑋等4人擔任上訴人之協商代表，且在工會代表欄簽名，而非僅係在場協助或列席之專業人士，即已違反團體協約法第8條第2項之規定。","arts":["8"],"src":"摘自本判決理由","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPAA%2c107%2c%e5%88%a4%2c270%2c20180510%2c1&ot=in"},{"id":"C107判270-1","type":"S","title":"最高行政法院107年度判字第270號判決","date":"","topic":"第9條第2項之追認，以協商代表合法推派、協商程序合法為前提","summary":"團體協約法第9條第2項規定：「未依前項規定所簽訂之團體協約，於補行前項程序追認前，不生效力。」惟上開規定係指工會已依團體協約法第8條規定合法推派團體協商代表參與協商，且協商之程序合於團體協約法規定，但團體協約尚未依第9條第1項之程序為決議或書面同意為前提，若未合法推派協商代表或協商程序不合團體協約法之規定，縱嗣後補行第9條第1項程序加以追認，亦無從發生追認之效力。","arts":["9","8"],"src":"摘自本判決理由","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPAA%2c107%2c%e5%88%a4%2c270%2c20180510%2c1&ot=in"},{"id":"C107判270-2","type":"S","title":"最高行政法院107年度判字第270號判決","date":"","topic":"一般性團體協議與團體協約之區別：綜合協議過程及內容客觀判斷","summary":"工會與雇主團體間所簽訂之協議，究屬一般性之團體協議，或屬團體協約法上之團體協約，應綜合協議之過程及內容，客觀加以判斷，而不能以協議當事人之主觀見解作為認定之依據，且法律見解之歧異或不同，亦不得作為認定是否構成不當勞動行為之依據。","arts":["2"],"src":"摘自本判決理由","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPAA%2c107%2c%e5%88%a4%2c270%2c20180510%2c1&ot=in"},{"id":"C109判421","type":"S","title":"最高行政法院109年度判字第421號判決","date":"","topic":"團體協約屆期後之餘後效力；列入協約之優待機票規定屬勞動條件","summary":"依上述團體協約法第21條規定及團體協約第77條約定，原團體協約關於勞動契約之約定，自仍繼續為該團體協約關係人間勞動契約之內容。而依該團體協約第62條約定：「乙方會員得依優待機票申請辦法所訂之資格及程序，向甲方申請優待機票。優待機票申請辦法修訂，如有影響員工權益時，將請乙方代表參與研議。」因此，優待機票申請辦法之修訂，既已經上訴人及參加人認對勞工之權益關係重大，而列為團體協約約定事項之一，應認已屬勞動條件之一部分。","arts":["21","12"],"src":"摘自本判決理由","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPAA%2c109%2c%e5%88%a4%2c421%2c20200806%2c1&ot=in"},{"id":"C110上142","type":"S","title":"最高行政法院110年度上字第142號判決","date":"","topic":"工會會員（保險業務員）是否為勞工，影響雇主有無誠信協商義務","summary":"保險業務員與其所屬保險公司所簽訂之保險招攬勞務契約，雖僅能販售該保險公司之保險契約，惟如保險業務員就其實質上從事招攬保險之勞務活動及工作時間得以自由決定，其報酬給付方式並無底薪及一定業績之要求，係自行負擔業務之風險，則其與所屬保險公司間之從屬性程度不高，尚難認屬上開所稱勞動契約等語。是以，本件上訴人與參加人間就參加人會員結清舊制年資事宜，是否互負有誠信協商義務，應就上訴人與參加人會員間所簽訂之契約性質而定。","arts":["6"],"src":"本判決廢棄原判決、發回更審","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPAA%2c110%2c%e4%b8%8a%2c142%2c20240826%2c1&ot=in"},{"id":"C113台上1906","type":"S","title":"最高法院113年度台上字第1906號民事判決","date":"","topic":"職業工會具協商資格，得為罷工主體","summary":"罷工係勞工為繼續維持、改善其勞動條件或獲取一定之經濟利益，依法定程序所為暫時拒絕提供勞務之爭議行為；又職業工會，係同一直轄市或縣（市）區域內，結合相關職業技能之勞工，所組織之工會；具有代表所屬會員（勞工）與特定雇主協商之資格（工會法第6條第1項第3款、第2項，團體協約法第6條第3項第3款規定參照），得作為罷工主體，即就權利事項以外之爭議，因與雇主調解不成立，為達所屬會員（勞工）勞動條件得以繼續維持或改善及其他經濟地位提升之目的，經有權參與集體意思表示形成之會員全體以直接、無記名投票經全體過半數同意（程序），決議罷工及設置糾察線。揆諸職業工會之組成、協商與罷工之目的，所謂有權參與投票者，應僅有爭議範圍所及之工會會員，不包括非爭議範圍所及之工會會員或其他非工會會員。","arts":["6"],"src":"摘自本判決理由","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPSV%2c113%2c%e5%8f%b0%e4%b8%8a%2c1906%2c20250424%2c1&ot=in"},{"id":"C113台上1906-1","type":"S","title":"最高法院113年度台上字第1906號民事判決","date":"","topic":"第12條第1項各款均屬得協商之勞動條件（勞工董事、外籍組員比例）；禁搭便車條款","summary":"故不採狹義解釋，即團體協約法第12條第1項各款所列事項，均屬勞動條件，針對雇主改善上開各款所定勞動條件為目的，所為之罷工應為合法。而設置勞工董事、限制外籍組員服勤人數，分屬團體協約法第12條第1項第5款「參與企業經營與勞資合作組織之設置及利用」與第2款「就業服務機構之利用」規定，得為團體協約協商之事項。雖選任董事，依公司法第192條第1項規定屬股東會之職權，然上訴人仍可就桃空職工此項訴求提出勞工董事候選人供股東會選任，或增加勞工董事之章程修改等對應方案；又參酌就業服務法第42條、第43條規定，聘僱外國人工作採申請許可制，故限制外籍組員服勤人數，係上訴人得承諾之處分事項，雖同法第5條第1項規定禁止「出生地」之就業歧視，然上訴人亦得提出限制僱用「依法取得許可在我國境內工作之外國人」，或「與中華民國境內設有戶籍之國民結婚，且獲准居留，依法在我國境內工作之外國人」以外之外國人，即無違反上訴人所舉改制前行政院勞工委員會93年勞職業字第0930204733號、102年勞綜4字第1020155155號函釋「出生地」就業歧視之情，且就桃空職工提出限制外籍組員服勤人數條款，關於限制僱用外國人之比例（即外籍客艙組員不得高於本國籍客艙組員人數之13%，各航班派遣外籍客艙組員不應超過2人），亦難認有犧牲上訴人利益以圖利桃空職工，致悖於正義公平之情形；另稽諸團體協約法第13條之規定暨其立法理由，有正當理由下，勞雇雙方得約定禁搭便車條款之團體協約，且桃空職工提出日支費絕對間距條款〔即上訴人應給付桃空職工會員日支費（perdiem）每小時150元，且不得給付非會員，若上訴人同時調升非會員日支費，須給付會員差額〕，與該條規定意旨大致相符，若上訴人認欠缺除外情形而無法同意，亦應本於誠信原則，提出對應方案進行協商。","arts":["12","13"],"src":"原審（臺灣高等法院）見解，經本判決認「經核於法並無違誤」而維持","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPSV%2c113%2c%e5%8f%b0%e4%b8%8a%2c1906%2c20250424%2c1&ot=in"},{"id":"C108判88","type":"S","title":"最高行政法院108年度判字第88號判決","date":"","topic":"公立學校教師之雇主為學校；教育主管機關行使第10條第2項第3款核可權，非協約當事人","summary":"參考團體協約法第10條第1項、第2項第3款及其立法理由可知，如將教育主管機關認為團體協約法所稱的雇主，則被上訴人將自行審查核可自己所簽訂的團體協約，團體協約法第10條第2項第3款規定將形同具文。可見學校於團體協約的協商及勞資爭議的處理才是一方當事人，公立學校教師的雇主為學校，教育主管機關不屬教師聘約的當事人，只對學校具有職務上的內部監督關係。","arts":["10","2"],"src":"原審見解，經本判決引述","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPAA%2c108%2c%e5%88%a4%2c88%2c20190227%2c1&ot=in"},{"id":"C781ec831","type":"A","title":"勞動部104年1月27日勞動關2字第1040051775號函","date":"","topic":"第10條第2項核可權（行政監督）與代表學校協商之角色不同","summary":"勞動部曾於104年1月27日以勞動關2字第1040051775號函復被上訴人詢問略以：團體協約法第10條第2項是規定公立學校上級機關基於業務主管目的的行政監督，而教育主管機關代表學校與工會協商團體協約，是代表學校與工會團體協商，以約定勞動關係相關事項，二者角色及立法目的均不相同等語。","arts":["10"],"src":"要旨摘自最高行政法院108年度判字第88號判決之引述","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPAA%2c108%2c%e5%88%a4%2c88%2c20190227%2c1&ot=in"},{"id":"C108勞裁20","type":"W","title":"勞動部108年勞裁字第20號不當勞動行為裁決決定","date":"","topic":"以函文拒絕與（金控與子公司）企業工會協商，構成違反第6條第1項","summary":"經被上訴人於民國108年10月4日以108年勞裁字第20號決定（下或稱系爭裁決），確認上訴人以108年4月19日函文拒絕與元大金控工會進行團體協商之行為，構成違反團體協約法第6條第1項之不當勞動行為，上訴人應自收到系爭裁決翌日起30日內與元大金控工會進行團體協商。","arts":["6","32"],"src":"要旨摘自最高行政法院111年度上字第439號判決之引述（該判決維持依第32條第2項所為之處分）","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPAA%2c111%2c%e4%b8%8a%2c439%2c20230921%2c1&ot=in"},{"id":"C6ffa9006","type":"A","title":"勞動部103年3月5日勞動關2字函","date":"","topic":"未簽訂團體協約時，勞動條件之變更無須經工會會員（代表）大會議決","summary":"若勞工所組成或加入之工會未與雇主約定團體協約，有關該勞工勞動條件之合意與變更，勞雇雙方仍得於勞動契約中約定之，無須經工會會員大會或會員代表大會之議決。","arts":["9"],"src":"要旨摘自臺灣高等法院102年度勞上易字第64號民事判決之引述（函號於裁判書中遮蔽）","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHV%2c102%2c%e5%8b%9e%e4%b8%8a%e6%98%93%2c64%2c20140429%2c2&ot=in"},{"id":"C106勞裁55","type":"W","title":"勞動部106年勞裁字第55號不當勞動行為裁決決定","date":"","topic":"團體協商期間違反第6條第1項及第2項第2款（未於60日內提出對應方案）","summary":"經勞動部不當勞動行為裁決委員會於107年1月26日以106年勞裁字第55號裁決確認原告於團體協商期間有構成團體協約法第6條第1項暨第6條第2項第2款不誠信協商之不當勞動行為。","arts":["6"],"src":"要旨摘自臺北高等行政法院109年度訴字第289號判決之引述","url":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPBA%2c109%2c%e8%a8%b4%2c289%2c20210107%2c1&ot=in"}],"refLaws":{"U":{"name":"工會法","short":"工會法","pcode":"N0020001","modified":"20220518","arts":{"1":[{"i":0,"t":"為促進勞工團結，提升勞工地位及改善勞工生活，特制定本法。"}],"2":[{"i":0,"t":"工會為法人。"}],"3":[{"i":0,"t":"本法所稱主管機關：在中央為勞動部；在直轄市為直轄市政府；在縣（市）為縣（市）政府。"},{"i":0,"t":"工會之目的事業，應受各該事業之主管機關輔導、監督。"}],"4":[{"i":0,"t":"勞工均有組織及加入工會之權利。"},{"i":0,"t":"現役軍人與國防部所屬及依法監督之軍火工業員工，不得組織工會；軍火工業之範圍，由中央主管機關會同國防部定之。"},{"i":0,"t":"教師得依本法組織及加入工會。"},{"i":0,"t":"各級政府機關及公立學校公務人員之結社組織，依其他法律之規定。"}],"5":[{"i":0,"t":"工會之任務如下："},{"i":4,"t":"一、團體協約之締結、修改或廢止。"},{"i":4,"t":"二、勞資爭議之處理。"},{"i":4,"t":"三、勞動條件、勞工安全衛生及會員福利事項之促進。"},{"i":4,"t":"四、勞工政策與法令之制（訂）定及修正之推動。"},{"i":4,"t":"五、勞工教育之舉辦。"},{"i":4,"t":"六、會員就業之協助。"},{"i":4,"t":"七、會員康樂事項之舉辦。"},{"i":4,"t":"八、工會或會員糾紛事件之調處。"},{"i":4,"t":"九、依法令從事事業之舉辦。"},{"i":4,"t":"十、勞工家庭生計之調查及勞工統計之編製。"},{"i":6,"t":"十一、其他合於第一條宗旨及法律規定之事項。"}],"6":[{"i":0,"t":"工會組織類型如下，但教師僅得組織及加入第二款及第三款之工會："},{"i":4,"t":"一、企業工會：結合同一廠場、同一事業單位、依公司法所定具有控制與從屬關係之企業，或依金融控股公司法所定金融控股公司與子公司內之勞工，所組織之工會。"},{"i":4,"t":"二、產業工會：結合相關產業內之勞工，所組織之工會。"},{"i":4,"t":"三、職業工會：結合相關職業技能之勞工，所組織之工會。"},{"i":0,"t":"前項第三款組織之職業工會，應以同一直轄市或縣（市）為組織區域。"}],"7":[{"i":0,"t":"依前條第一項第一款組織之企業工會，其勞工應加入工會。"}],"8":[{"i":0,"t":"工會得依需要籌組聯合組織；其名稱、層級、區域及屬性，應於聯合組織章程中定之。"},{"i":0,"t":"工會聯合組織應置專任會務人員辦理會務。"},{"i":0,"t":"以全國為組織區域籌組之工會聯合組織，其發起籌組之工會數應達發起工會種類數額三分之一以上，且所含行政區域應達全國直轄市、縣（市）總數二分之一以上。"}],"9":[{"i":0,"t":"依本法第六條第一項所組織之各企業工會，以組織一個為限。"},{"i":0,"t":"同一直轄市或縣（市）內之同種類職業工會，以組織一個為限。"}],"10":[{"i":0,"t":"工會名稱，不得與其他工會名稱相同。"}],"11":[{"i":0,"t":"組織工會應有勞工三十人以上之連署發起，組成籌備會辦理公開徵求會員、擬定章程及召開成立大會。"},{"i":0,"t":"前項籌備會應於召開工會成立大會後三十日內，檢具章程、會員名冊及理事、監事名冊，向其會址所在地之直轄市或縣（市）主管機關請領登記證書。但依第八條規定以全國為組織區域籌組之工會聯合組織，應向中央主管機關登記，並請領登記證書。"}],"12":[{"i":0,"t":"工會章程之記載事項如下："},{"i":4,"t":"一、名稱。"},{"i":4,"t":"二、宗旨。"},{"i":4,"t":"三、區域。"},{"i":4,"t":"四、會址。"},{"i":4,"t":"五、任務。"},{"i":4,"t":"六、組織。"},{"i":4,"t":"七、會員入會、出會、停權及除名。"},{"i":4,"t":"八、會員之權利及義務。"},{"i":4,"t":"九、會員代表、理事、監事之名額、權限及其選任、解任、停權；置有常務理事、常務監事及副理事長者，亦同。"},{"i":4,"t":"十、置有秘書長或總幹事者，其聘任及解任。"},{"i":6,"t":"十一、理事長與監事會召集人之權限及選任、解任、停權。"},{"i":6,"t":"十二、會議。"},{"i":6,"t":"十三、經費及會計。"},{"i":6,"t":"十四、基金之設立及管理。"},{"i":6,"t":"十五、財產之處分。"},{"i":6,"t":"十六、章程之修改。"},{"i":6,"t":"十七、其他依法令規定應載明之事項。"}],"13":[{"i":0,"t":"工會章程之訂定，應經成立大會會員或會員代表過半數之出席，並經出席會員或會員代表三分之二以上之同意。"}],"14":[{"i":0,"t":"代表雇主行使管理權之主管人員，不得加入該企業之工會。但工會章程另有規定者，不在此限。"}],"15":[{"i":0,"t":"工會會員人數在一百人以上者，得依章程選出會員代表。"},{"i":0,"t":"工會會員代表之任期，每一任不得超過四年，自當選後召開第一次會員代表大會之日起算。"}],"16":[{"i":0,"t":"工會會員大會為工會之最高權力機關。但工會設有會員代表大會者，由會員代表大會行使會員大會之職權。"}],"17":[{"i":0,"t":"工會應置理事及監事，其名額如下："},{"i":4,"t":"一、工會會員人數五百人以下者，置理事五人至九人；其會員人數超過五百人者，每逾五百人得增置理事二人，理事名額最多不得超過二十七人。"},{"i":4,"t":"二、工會聯合組織之理事不得超過五十一人。"},{"i":4,"t":"三、工會之監事不得超過該工會理事名額三分之一。"},{"i":0,"t":"前項各款理事、監事名額在三人以上時，得按其章程規定推選常務理事、常務監事；其名額不得超過理事、監事名額三分之一。工會得置候補理事、候補監事至少一人；其名額不得超過該工會理事、監事名額二分之一。"},{"i":0,"t":"工會應置理事長一人，對外代表工會，並得視業務需要置副理事長。理事長、副理事長應具理事身分。"},{"i":0,"t":"工會監事名額在三人以上者，應設監事會，置監事會召集人一人。監事會召集人執行監事會決議，並列席理事會。"}],"18":[{"i":0,"t":"會員大會或會員代表大會休會期間，由理事會處理工會一切事務。"},{"i":0,"t":"工會監事審核工會簿記帳目，稽查各種事業進行狀況及章程所定之事項，並得會同相關專業人士為之。"},{"i":0,"t":"監事之職權於設有監事會之工會，由監事會行使之。"}],"19":[{"i":0,"t":"工會會員已成年者，得被選舉為工會之理事、監事。"},{"i":0,"t":"工會會員參加工業團體或商業團體者，不得為理事或監事、常務理事、常務監事、副理事長、理事長或監事會召集人。"}],"20":[{"i":0,"t":"工會理事、監事、常務理事、常務監事、副理事長、理事長及監事會召集人之任期，每一任不得超過四年。"},{"i":0,"t":"理事長連選得連任一次。"}],"21":[{"i":0,"t":"工會理事、監事、常務理事、常務監事、副理事長、理事長、監事會召集人及其代理人，因執行職務所致他人之損害，工會應負連帶責任。"}],"22":[{"i":0,"t":"工會召開會議時，其會議通知之記載事項如下："},{"i":4,"t":"一、事由。"},{"i":4,"t":"二、時間。"},{"i":4,"t":"三、地點。"},{"i":4,"t":"四、其他事項。"}],"23":[{"i":0,"t":"工會會員大會或會員代表大會，分定期會議及臨時會議二種，由理事長召集之。"},{"i":0,"t":"定期會議，每年至少召開一次，至遲應於會議召開當日之十五日前，將會議通知送達會員或會員代表。"},{"i":0,"t":"臨時會議，經理事會決議，或會員五分之一或會員代表三分之一以上請求，或監事之請求，由理事長召集之，至遲應於會議召開當日之三日前，將會議通知送達會員或會員代表。但因緊急事故召集臨時會議，得於會議召開當日之一日前送達。"}],"24":[{"i":0,"t":"工會理事會分為定期會議及臨時會議二種，由理事長召集之。"},{"i":0,"t":"定期會議，每三個月至少開會一次，至遲應於會議召開當日之七日前，將會議通知送達理事。"},{"i":0,"t":"臨時會議，經理事三分之一以上之請求，由理事長召集之，至遲應於會議召開當日之一日前，將會議通知送達理事。理事長認有必要時，亦得召集之。"},{"i":0,"t":"理事應親自出席會議。"},{"i":0,"t":"工會設監事會者，其定期會議或臨時會議準用前四項規定；會議應由監事會召集人召集之。"},{"i":0,"t":"監事得列席理事會陳述意見。"}],"25":[{"i":0,"t":"前二條之定期會議，不能依法或依章程規定召開時，得由主管機關指定理事或監事一人召集之。"},{"i":0,"t":"前二條之臨時會議，理事長或監事會召集人不於請求之日起十日內召集時，原請求人之一人或數人得申請主管機關指定召集之。"}],"26":[{"i":0,"t":"下列事項應經會員大會或會員代表大會之議決："},{"i":4,"t":"一、工會章程之修改。"},{"i":4,"t":"二、財產之處分。"},{"i":4,"t":"三、工會之聯合、合併、分立或解散。"},{"i":4,"t":"四、會員代表、理事、監事、常務理事、常務監事、副理事長、理事長、監事會召集人之選任、解任及停權之規定。"},{"i":4,"t":"五、會員之停權及除名之規定。"},{"i":4,"t":"六、工會各項經費收繳數額、經費之收支預算、支配基準與支付及稽核方法。"},{"i":4,"t":"七、事業報告及收支決算之承認。"},{"i":4,"t":"八、基金之運用及處分。"},{"i":4,"t":"九、會內公共事業之創辦。"},{"i":4,"t":"十、集體勞動條件之維持或變更。"},{"i":6,"t":"十一、其他與會員權利義務有關之重大事項。"},{"i":0,"t":"前項第四款之規定經議決訂定者，不受人民團體法及其相關法令之限制。"},{"i":0,"t":"會員之停權或除名，於會員大會或會員代表大會議決前，應給予其陳述意見之機會。"}],"27":[{"i":0,"t":"工會會員大會或會員代表大會，應有會員或會員代表過半數出席，始得開會；非有出席會員或會員代表過半數同意，不得議決。但前條第一項第一款至第五款之事項，非有出席會員或會員代表三分之二以上同意，不得議決。"},{"i":0,"t":"會員或會員代表因故無法出席會議時，得以書面委託其他會員或會員代表出席，每一代表以委託一人為限，委託人數不得超過親自出席人數之三分之一；其委託方式、條件、委託數額計算及其他應遵循事項之辦法，由中央主管機關定之。"},{"i":0,"t":"工會聯合組織之會員代表委託代表出席時，其委託除應依前項規定辦理外，並僅得委託所屬工會或各該本業之其他會員代表。"}],"28":[{"i":0,"t":"工會經費來源如下："},{"i":4,"t":"一、入會費。"},{"i":4,"t":"二、經常會費。"},{"i":4,"t":"三、基金及其孳息。"},{"i":4,"t":"四、舉辦事業之利益。"},{"i":4,"t":"五、委託收入。"},{"i":4,"t":"六、捐款。"},{"i":4,"t":"七、政府補助。"},{"i":4,"t":"八、其他收入。"},{"i":0,"t":"前項入會費，每人不得低於其入會時之一日工資所得。經常會費不得低於該會員當月工資之百分之零點五。"},{"i":0,"t":"企業工會經會員同意，雇主應自該勞工加入工會為會員之日起，自其工資中代扣工會會費，轉交該工會。"},{"i":0,"t":"會員工會對工會聯合組織之會費繳納，應按申報參加工會聯合組織之人數繳納之。但工會聯合組織之章程另有規定者，從其規定。"},{"i":0,"t":"前項繳納會費之標準，最高不得超過會員工會會員所繳會費總額之百分之三十，最低不得少於百分之五。但工會聯合組織之章程另有規定者，從其規定。"}],"29":[{"i":0,"t":"工會每年應將財產狀況向會員大會或會員代表大會提出書面報告。會員經十分之一以上連署或會員代表經三分之一以上連署，得選派代表會同監事查核工會之財產狀況。"}],"30":[{"i":0,"t":"工會應建立財務收支運用及稽核機制。"},{"i":0,"t":"工會財務事務處理之項目、會計報告、預算及決算編製、財產管理、財務查核及其他應遵行事項之準則，由中央主管機關定之。"}],"31":[{"i":0,"t":"工會應於每年年度決算後三十日內，將下列事項，報請主管機關備查："},{"i":4,"t":"一、理事、監事、常務理事、常務監事、副理事長、理事長及監事會召集人之名冊。"},{"i":4,"t":"二、會員入會、出會名冊。"},{"i":4,"t":"三、聯合組織之會員工會名冊。"},{"i":4,"t":"四、財務報表。"},{"i":4,"t":"五、會務及事業經營之狀況。"},{"i":0,"t":"工會未依前項規定辦理或主管機關認有必要時，得限期令其檢送或派員查核。"}],"32":[{"i":0,"t":"工會章程之修改或理事、監事、常務理事、常務監事、副理事長、理事長、監事會召集人之變更，應報請主管機關備查。"}],"33":[{"i":0,"t":"工會會員大會或會員代表大會之召集程序或決議方法，違反法令或章程時，會員或會員代表得於決議後三十日內，訴請法院撤銷其決議。但出席會議之會員或會員代表未當場表示異議者，不得為之。"},{"i":0,"t":"法院對於前項撤銷決議之訴，認為其違反之事實非屬重大且於決議無影響者，得駁回其請求。"}],"34":[{"i":0,"t":"工會會員大會或會員代表大會之決議內容違反法令或章程者，無效。"}],"35":[{"i":0,"t":"雇主或代表雇主行使管理權之人，不得有下列行為："},{"i":4,"t":"一、對於勞工組織工會、加入工會、參加工會活動或擔任工會職務，而拒絕僱用、解僱、降調、減薪或為其他不利之待遇。"},{"i":4,"t":"二、對於勞工或求職者以不加入工會或擔任工會職務為僱用條件。"},{"i":4,"t":"三、對於勞工提出團體協商之要求或參與團體協商相關事務，而拒絕僱用、解僱、降調、減薪或為其他不利之待遇。"},{"i":4,"t":"四、對於勞工參與或支持爭議行為，而解僱、降調、減薪或為其他不利之待遇。"},{"i":4,"t":"五、不當影響、妨礙或限制工會之成立、組織或活動。"},{"i":0,"t":"雇主或代表雇主行使管理權之人，為前項規定所為之解僱、降調或減薪者，無效。"}],"36":[{"i":0,"t":"工會之理事、監事於工作時間內有辦理會務之必要者，工會得與雇主約定，由雇主給予一定時數之公假。"},{"i":0,"t":"企業工會與雇主間無前項之約定者，其理事長得以半日或全日，其他理事或監事得於每月五十小時之範圍內，請公假辦理會務。"},{"i":0,"t":"企業工會理事、監事擔任全國性工會聯合組織理事長，其與雇主無第一項之約定者，得以半日或全日請公假辦理會務。"}],"37":[{"i":0,"t":"工會有下列情形之一者，得經會員大會或會員代表大會議決，自行宣告解散："},{"i":4,"t":"一、破產。"},{"i":4,"t":"二、會員人數不足。"},{"i":4,"t":"三、合併或分立。"},{"i":4,"t":"四、其他經會員大會或會員代表大會認有必要時。"},{"i":0,"t":"工會無法依前項第一款至第三款規定自行宣告解散或無從依章程運作時，法院得因主管機關、檢察官或利害關係人之聲請解散之。"}],"38":[{"i":0,"t":"工會經議決為合併或分立時，應於議決之日起一年內完成合併或分立。"},{"i":0,"t":"企業工會因廠場或事業單位合併時，應於合併基準日起一年內完成工會合併。屆期未合併者，主管機關得令其限期改善，未改善者，令其重新組織。"},{"i":0,"t":"工會依前二項規定為合併或分立時，應於完成合併或分立後三十日內，將其過程、工會章程、理事、監事名冊等，報請主管機關備查。"},{"i":0,"t":"行政組織區域變更時，工會經會員大會或會員代表大會議決，得維持工會原名稱。但工會名稱變更者，應於行政組織區域變更後九十日內，將會議紀錄函請主管機關備查。工會名稱變更者，不得與登記有案之工會相同。"},{"i":0,"t":"依前項規定議決之工會，其屆次之起算，應經會員大會或會員代表大會議決。"}],"39":[{"i":0,"t":"工會合併後存續或新成立之工會，應概括承受因合併而消滅工會之權利義務。"},{"i":0,"t":"因分立而成立之工會，其承繼權利義務之部分，應於議決分立時由會員大會或會員代表大會一併議決之。"}],"40":[{"i":0,"t":"工會自行宣告解散者，應於解散後十五日內，將其解散事由及時間，報請主管機關備查。"}],"41":[{"i":0,"t":"工會之解散，除因破產、合併或組織變更外，其財產應辦理清算。"}],"42":[{"i":0,"t":"工會解散時，除清償債務外，其賸餘財產之歸屬，應依其章程之規定、會員大會或會員代表大會之決議。但不得歸屬於個人或以營利為目的之團體。"},{"i":0,"t":"工會無法依前項規定處理時，其賸餘財產歸屬於會址所在地之地方自治團體。"}],"43":[{"i":0,"t":"工會有違反法令或章程者，主管機關得予以警告或令其限期改善。必要時，並得於限期改善前，令其停止業務之一部或全部。"},{"i":0,"t":"工會違反法令或章程情節重大，或經限期改善屆期仍未改善者，得撤免其理事、監事、理事長或監事會召集人。"}],"44":[{"i":0,"t":"主管機關依第三十一條第二項規定派員查核或限期檢送同條第一項資料時，工會無正當理由規避、妨礙、拒絕或未於限期內檢送資料者，處行為人新臺幣三萬元以上十五萬元以下罰鍰。"}],"45":[{"i":0,"t":"雇主或代表雇主行使管理權之人違反第三十五條第一項規定，經依勞資爭議處理法裁決決定者，由中央主管機關處雇主新臺幣十萬元以上五十萬元以下罰鍰，並公布其名稱、代表人姓名、處分期日、違反條文及罰鍰金額。"},{"i":0,"t":"雇主或代表雇主行使管理權之人違反第三十五條第一項第一款、第三款或第四款規定，未依前項裁決決定書所定期限為一定之行為或不行為者，由中央主管機關處雇主新臺幣二十萬元以上一百萬元以下罰鍰。"},{"i":0,"t":"雇主或代表雇主行使管理權之人違反第三十五條第一項第二款或第五款規定，未依第一項裁決決定書所定期限為一定之行為或不行為者，由中央主管機關處雇主新臺幣二十萬元以上一百萬元以下罰鍰，並得令其限期改正；屆期未改正者，得按次連續處罰。"}],"46":[{"i":0,"t":"雇主未依第三十六條第二項規定給予公假者，處新臺幣二萬元以上十萬元以下罰鍰。"}],"47":[{"i":0,"t":"本法施行前已組織之工會，其名稱、章程、理事及監事名額或任期與本法規定不符者，應於最近一次召開會員大會或會員代表大會時改正之。"}],"48":[{"i":0,"t":"本法施行細則，由中央主管機關定之。"}],"49":[{"i":0,"t":"本法施行日期，由行政院定之。"}]}},"P":{"name":"勞資爭議處理法","short":"勞爭法","pcode":"N0020007","arts":{"1":[{"i":0,"t":"為處理勞資爭議，保障勞工權益，穩定勞動關係，特制定本法。"}],"2":[{"i":0,"t":"勞資雙方當事人應本誠實信用及自治原則，解決勞資爭議。"}],"3":[{"i":0,"t":"本法於雇主或有法人資格之雇主團體（以下簡稱雇主團體）與勞工或工會發生勞資爭議時，適用之。但教師之勞資爭議屬依法提起行政救濟之事項者，不適用之。"}],"4":[{"i":0,"t":"本法所稱主管機關：在中央為勞動部；在直轄市為直轄市政府；在縣（市）為縣（市）政府。"}],"5":[{"i":0,"t":"本法用詞，定義如下："},{"i":4,"t":"一、勞資爭議：指權利事項及調整事項之勞資爭議。"},{"i":4,"t":"二、權利事項之勞資爭議：指勞資雙方當事人基於法令、團體協約、勞動契約之規定所為權利義務之爭議。"},{"i":4,"t":"三、調整事項之勞資爭議：指勞資雙方當事人對於勞動條件主張繼續維持或變更之爭議。"},{"i":4,"t":"四、爭議行為：指勞資爭議當事人為達成其主張，所為之罷工或其他阻礙事業正常運作及與之對抗之行為。"},{"i":4,"t":"五、罷工：指勞工所為暫時拒絕提供勞務之行為。"}],"6":[{"i":0,"t":"權利事項之勞資爭議，得依本法所定之調解、仲裁或裁決程序處理之。"},{"i":0,"t":"法院為審理權利事項之勞資爭議，必要時應設勞工法庭。"},{"i":0,"t":"權利事項之勞資爭議，勞方當事人有下列情形之一者，中央主管機關得給予適當扶助："},{"i":4,"t":"一、提起訴訟。"},{"i":4,"t":"二、依仲裁法提起仲裁。"},{"i":4,"t":"三、因工會法第三十五條第一項第一款至第四款所定事由，依本法申請裁決。"},{"i":0,"t":"前項扶助業務，中央主管機關得委託民間團體辦理。"},{"i":0,"t":"前二項扶助之申請資格、扶助範圍、審核方式及委託辦理等事項之辦法，由中央主管機關定之。"}],"7":[{"i":0,"t":"調整事項之勞資爭議，依本法所定之調解、仲裁程序處理之。"},{"i":0,"t":"前項勞資爭議之勞方當事人，應為工會。但有下列情形者，亦得為勞方當事人："},{"i":4,"t":"一、未加入工會，而具有相同主張之勞工達十人以上。"},{"i":4,"t":"二、受僱於僱用勞工未滿十人之事業單位，其未加入工會之勞工具有相同主張者達三分之二以上。"}],"8":[{"i":0,"t":"勞資爭議在調解、仲裁或裁決期間，資方不得因該勞資爭議事件而歇業、停工、終止勞動契約或為其他不利於勞工之行為；勞方不得因該勞資爭議事件而罷工或為其他爭議行為。"}],"9":[{"i":0,"t":"勞資爭議當事人一方申請調解時，應向勞方當事人勞務提供地之直轄市或縣（市）主管機關提出調解申請書。"},{"i":0,"t":"前項爭議當事人一方為團體協約法第十條第二項規定之機關（構）、學校者，其出席調解時之代理人應檢附同條項所定有核可權機關之同意書。"},{"i":0,"t":"第一項直轄市、縣（市）主管機關對於勞資爭議認為必要時，得依職權交付調解，並通知勞資爭議雙方當事人。"},{"i":0,"t":"第一項及前項調解，其勞方當事人有二人以上者，各勞方當事人勞務提供地之主管機關，就該調解案件均有管轄權。"}],"10":[{"i":0,"t":"調解之申請，應提出調解申請書，並載明下列事項："},{"i":4,"t":"一、當事人姓名、性別、年齡、職業及住所或居所；如為法人、雇主團體或工會時，其名稱、代表人及事務所或營業所；有代理人者，其姓名、名稱及住居所或事務所。"},{"i":4,"t":"二、請求調解事項。"},{"i":4,"t":"三、依第十一條第一項選定之調解方式。"}],"11":[{"i":0,"t":"直轄市或縣（市）主管機關受理調解之申請，應依申請人之請求，以下列方式之一進行調解："},{"i":4,"t":"一、指派調解人。"},{"i":4,"t":"二、組成勞資爭議調解委員會（以下簡稱調解委員會）。"},{"i":0,"t":"直轄市或縣（市）主管機關依職權交付調解者，得依前項方式之一進行調解。"},{"i":0,"t":"第一項第一款之調解，直轄市、縣（市）主管機關得委託民間團體指派調解人進行調解。"},{"i":0,"t":"第一項調解之相關處理程序、充任調解人或調解委員之遴聘條件與前項受託民間團體之資格及其他應遵行事項之辦法，由中央主管機關定之。"},{"i":0,"t":"主管機關對第三項之民間團體，除委託費用外，並得予補助。"}],"12":[{"i":0,"t":"直轄市或縣（市）主管機關指派調解人進行調解者，應於收到調解申請書三日內為之。"},{"i":0,"t":"調解人應調查事實，並於指派之日起七日內開始進行調解。"},{"i":0,"t":"直轄市或縣（市）主管機關於調解人調查時，得通知當事人、相關人員或事業單位，以言詞或書面提出說明；調解人為調查之必要，得經主管機關同意，進入相關事業單位訪查。"},{"i":0,"t":"前項受通知或受訪查人員，不得為虛偽說明、提供不實資料或無正當理由拒絕說明。"},{"i":0,"t":"調解人應於開始進行調解十日內作出調解方案，並準用第十九條、第二十條及第二十二條之規定。"}],"13":[{"i":0,"t":"調解委員會置委員三人或五人，由下列代表組成之，並以直轄市或縣（市）主管機關代表一人為主席："},{"i":4,"t":"一、直轄市、縣（市）主管機關指派一人或三人。"},{"i":4,"t":"二、勞資爭議雙方當事人各自選定一人。"}],"14":[{"i":0,"t":"直轄市、縣（市）主管機關以調解委員會方式進行調解者，應於收到調解申請書或職權交付調解後通知勞資爭議雙方當事人於收到通知之日起三日內各自選定調解委員，並將調解委員之姓名、性別、年齡、職業及住居所具報；屆期未選定者，由直轄市、縣（市）主管機關代為指定。"},{"i":0,"t":"前項主管機關得備置調解委員名冊，以供參考。"}],"15":[{"i":0,"t":"直轄市、縣（市）主管機關以調解委員會方式進行調解者，應於調解委員完成選定或指定之日起十四日內，組成調解委員會並召開調解會議。"}],"16":[{"i":0,"t":"調解委員會應指派委員調查事實，除有特殊情形外，該委員應於受指派後十日內，將調查結果及解決方案提報調解委員會。"},{"i":0,"t":"調解委員會應於收到前項調查結果及解決方案後十五日內開會。必要時或經勞資爭議雙方當事人同意者，得延長七日。"}],"17":[{"i":0,"t":"調解委員會開會時，調解委員應親自出席，不得委任他人代理；受指派調查時，亦同。"},{"i":0,"t":"直轄市、縣（市）主管機關於調解委員調查或調解委員會開會時，得通知當事人、相關人員或事業單位以言詞或書面提出說明；調解委員為調查之必要，得經主管機關同意，進入相關事業單位訪查。"},{"i":0,"t":"前項受通知或受訪查人員，不得為虛偽說明、提供不實資料或無正當理由拒絕說明。"}],"18":[{"i":0,"t":"調解委員會應有調解委員過半數出席，始得開會；經出席委員過半數同意，始得決議，作成調解方案。"}],"19":[{"i":0,"t":"依前條規定作成之調解方案，經勞資爭議雙方當事人同意在調解紀錄簽名者，為調解成立。但當事人之一方為團體協約法第十條第二項規定之機關（構）、學校者，其代理人簽名前，應檢附同條項所定有核可權機關之同意書。"}],"20":[{"i":0,"t":"勞資爭議當事人對調解委員會之調解方案不同意者，為調解不成立。"}],"21":[{"i":0,"t":"有下列情形之一者，視為調解不成立："},{"i":4,"t":"一、經調解委員會主席召集會議，連續二次調解委員出席人數未過半數。"},{"i":4,"t":"二、未能作成調解方案。"}],"22":[{"i":0,"t":"勞資爭議調解成立或不成立，調解紀錄均應由調解委員會報由直轄市、縣（市）主管機關送達勞資爭議雙方當事人。"}],"23":[{"i":0,"t":"勞資爭議經調解成立者，視為爭議雙方當事人間之契約；當事人一方為工會時，視為當事人間之團體協約。"}],"24":[{"i":0,"t":"勞資爭議調解人、調解委員、參加調解及經辦調解事務之人員，對於調解事件，除已公開之事項外，應保守秘密。"}],"25":[{"i":0,"t":"勞資爭議調解不成立者，雙方當事人得共同向直轄市或縣（市）主管機關申請交付仲裁。但調整事項之勞資爭議，當事人一方為團體協約法第十條第二項規定之機關（構）、學校時，非經同條項所定機關之核可，不得申請仲裁。"},{"i":0,"t":"勞資爭議當事人之一方為第五十四條第二項之勞工者，其調整事項之勞資爭議，任一方得向直轄市或縣（市）申請交付仲裁；其屬同條第三項事業調整事項之勞資爭議，而雙方未能約定必要服務條款者，任一方得向中央主管機關申請交付仲裁。"},{"i":0,"t":"勞資爭議經雙方當事人書面同意，得不經調解，逕向直轄市或縣（市）主管機關申請交付仲裁。"},{"i":0,"t":"調整事項之勞資爭議經調解不成立者，直轄市或縣（市）主管機關認有影響公眾生活及利益情節重大，或應目的事業主管機關之請求，得依職權交付仲裁，並通知雙方當事人。"}],"26":[{"i":0,"t":"主管機關受理仲裁之申請，應依申請人之請求，以下列方式之一進行仲裁，其為一方申請交付仲裁或依職權交付仲裁者，僅得以第二款之方式為之："},{"i":4,"t":"一、選定獨任仲裁人。"},{"i":4,"t":"二、組成勞資爭議仲裁委員會（以下簡稱仲裁委員會）。"},{"i":0,"t":"前項仲裁人與仲裁委員之資格條件、遴聘方式、選定及仲裁程序及其他應遵行事項之辦法，由中央主管機關定之。"}],"27":[{"i":0,"t":"雙方當事人合意以選定獨任仲裁人方式進行仲裁者，直轄市或縣（市）主管機關應於收到仲裁申請書後，通知勞資爭議雙方當事人於收到通知之日起五日內，於直轄市、縣（市）主管機關遴聘之仲裁人名冊中選定獨任仲裁人一人具報；屆期未選定者，由直轄市、縣（市）主管機關代為指定。"},{"i":0,"t":"前項仲裁人名冊，由直轄市、縣（市）主管機關遴聘具一定資格之公正並富學識經驗者充任、彙整之，並應報請中央主管機關備查。"},{"i":0,"t":"第三十二條、第三十三條及第三十五條至第三十七條之規定，於獨任仲裁人仲裁程序準用之。"}],"28":[{"i":0,"t":"申請交付仲裁者，應提出仲裁申請書，並檢附調解紀錄或不經調解之同意書；其為一方申請交付仲裁者，並應檢附符合第二十五條第二項規定之證明文件。"}],"29":[{"i":0,"t":"以組成仲裁委員會方式進行仲裁者，主管機關應於收到仲裁申請書或依職權交付仲裁後，通知勞資爭議雙方當事人於收到通知之日起五日內，於主管機關遴聘之仲裁委員名冊中各自選定仲裁委員具報；屆期未選定者，由主管機關代為指定。"},{"i":0,"t":"勞資雙方仲裁委員經選定或指定後，主管機關應於三日內通知雙方仲裁委員，於七日內依第三十條第一項及第二項或第四項規定推選主任仲裁委員及其餘仲裁委員具報；屆期未推選者，由主管機關指定。"}],"30":[{"i":0,"t":"仲裁委員會置委員三人或五人，由下列人員組成之："},{"i":4,"t":"一、勞資爭議雙方當事人各選定一人。"},{"i":4,"t":"二、由雙方當事人所選定之仲裁委員於仲裁委員名冊中，共同選定一人或三人。"},{"i":0,"t":"前項仲裁委員會置主任仲裁委員一人，由前項第二款委員互推一人擔任，並為會議主席。"},{"i":0,"t":"仲裁委員由直轄市、縣（市）主管機關遴聘具一定資格之公正並富學識經驗者任之。直轄市、縣（市）主管機關遴聘後，應報請中央主管機關備查。"},{"i":0,"t":"依第二十五條第二項規定由中央主管機關交付仲裁者，其仲裁委員會置委員五人或七人，由勞資爭議雙方當事人各選定二人之外，再共同另選定一人或三人，並由共同選定者互推一人為主任仲裁委員，並為會議主席。"},{"i":0,"t":"前項仲裁委員名冊，由中央主管機關會商相關目的事業主管機關後遴聘之。"}],"31":[{"i":0,"t":"主管機關應於主任仲裁委員完成選定或指定之日起十四日內，組成仲裁委員會，並召開仲裁會議。"}],"32":[{"i":0,"t":"有下列情形之一者，不得擔任同一勞資爭議事件之仲裁委員："},{"i":4,"t":"一、曾為該爭議事件之調解委員。"},{"i":4,"t":"二、本人或其配偶、前配偶或與其訂有婚約之人為爭議事件當事人，或與當事人有共同權利人、共同義務人或償還義務人之關係。"},{"i":4,"t":"三、為爭議事件當事人八親等內之血親或五親等內之姻親，或曾有此親屬關係。"},{"i":4,"t":"四、現為或曾為該爭議事件當事人之代理人或家長、家屬。"},{"i":4,"t":"五、工會為爭議事件之當事人者，其會員、理事、監事或會務人員。"},{"i":4,"t":"六、雇主團體或雇主為爭議事件之當事人者，其會員、理事、監事、會務人員或其受僱人。"},{"i":0,"t":"仲裁委員有前項各款所列情形之一而不自行迴避，或有具體事實足認其執行職務有偏頗之虞者，爭議事件當事人得向主管機關申請迴避，其程序準用行政程序法第三十三條規定。"}],"33":[{"i":0,"t":"仲裁委員會應指派委員調查事實，除有特殊情形外，調查委員應於指派後十日內，提出調查結果。"},{"i":0,"t":"仲裁委員會應於收到前項調查結果後二十日內，作成仲裁判斷。但經勞資爭議雙方當事人同意，得延長十日。"},{"i":0,"t":"主管機關於仲裁委員調查或仲裁委員會開會時，應通知當事人、相關人員或事業單位以言詞或書面提出說明；仲裁委員為調查之必要，得經主管機關同意後，進入相關事業單位訪查。"},{"i":0,"t":"前項受通知或受訪查人員，不得為虛偽說明、提供不實資料或無正當理由拒絕說明。"}],"34":[{"i":0,"t":"仲裁委員會由主任仲裁委員召集，其由委員三人組成者，應有全體委員出席，經出席委員過半數同意，始得作成仲裁判斷；其由委員五人或七人組成者，應有三分之二以上委員出席，經出席委員四分之三以上同意，始得作成仲裁判斷。"},{"i":0,"t":"仲裁委員連續二次不參加會議，當然解除其仲裁職務，由主管機關另行指定仲裁委員代替之。"}],"35":[{"i":0,"t":"仲裁委員會作成仲裁判斷後，應於十日內作成仲裁判斷書，報由主管機關送達勞資爭議雙方當事人。"}],"36":[{"i":0,"t":"勞資爭議當事人於仲裁程序進行中和解者，應將和解書報仲裁委員會及主管機關備查，仲裁程序即告終結；其和解與依本法成立之調解有同一效力。"}],"37":[{"i":0,"t":"仲裁委員會就權利事項之勞資爭議所作成之仲裁判斷，於當事人間，與法院之確定判決有同一效力。"},{"i":0,"t":"仲裁委員會就調整事項之勞資爭議所作成之仲裁判斷，視為爭議當事人間之契約；當事人一方為工會時，視為當事人間之團體協約。"},{"i":0,"t":"對於前二項之仲裁判斷，勞資爭議當事人得準用仲裁法第五章之規定，對於他方提起撤銷仲裁判斷之訴。"},{"i":0,"t":"調整事項經作成仲裁判斷者，勞資雙方當事人就同一爭議事件不得再為爭議行為；其依前項規定向法院提起撤銷仲裁判斷之訴者，亦同。"}],"38":[{"i":0,"t":"第九條第四項、第十條、第十七條第一項及第二十四條之規定，於仲裁程序準用之。"}],"39":[{"i":0,"t":"勞工因工會法第三十五條第二項規定所生爭議，得向中央主管機關申請裁決。"},{"i":0,"t":"前項裁決之申請，應自知悉有違反工會法第三十五條第二項規定之事由或事實發生之次日起九十日內為之。"}],"40":[{"i":0,"t":"裁決之申請，應以書面為之，並載明下列事項："},{"i":4,"t":"一、當事人之姓名、性別、年齡、職業及住所或居所；如為法人、雇主團體或工會，其名稱、代表人及事務所或營業所；有代理人者，其姓名、名稱及住居所或事務所。"},{"i":4,"t":"二、請求裁決之事項及其原因事實。"}],"41":[{"i":0,"t":"基於工會法第三十五條第二項規定所為之裁決申請，違反第三十九條第二項及前條規定者，裁決委員應作成不受理之決定。但其情形可補正者，應先限期令其補正。"},{"i":0,"t":"前項不受理決定，不得聲明不服。"}],"42":[{"i":0,"t":"當事人就工會法第三十五條第二項所生民事爭議事件申請裁決，於裁決程序終結前，法院應依職權停止民事訴訟程序。"},{"i":0,"t":"當事人於第三十九條第二項所定期間提起之訴訟，依民事訴訟法之規定視為調解之聲請者，法院仍得進行調解程序。"},{"i":0,"t":"裁決之申請，除經撤回者外，與起訴有同一效力，消滅時效因而中斷。"}],"43":[{"i":0,"t":"中央主管機關為辦理裁決事件，應組成不當勞動行為裁決委員會（以下簡稱裁決委員會）。"},{"i":0,"t":"裁決委員會應秉持公正立場，獨立行使職權。"},{"i":0,"t":"裁決委員會置裁決委員七人至十五人，均為兼職，其中一人至三人為常務裁決委員，由中央主管機關遴聘熟悉勞工法令、勞資關係事務之專業人士任之，任期二年，並由委員互推一人為主任裁決委員。"},{"i":0,"t":"中央主管機關應調派專任人員或聘用專業人員，承主任裁決委員之命，協助辦理裁決案件之程序審查、爭點整理及資料蒐集等事務。具專業證照執業資格者，經聘用之期間，計入其專業執業年資。"},{"i":0,"t":"裁決委員會之組成、裁決委員之資格條件、遴聘方式、裁決委員會相關處理程序、前項人員之調派或遴聘及其他應遵行事項之辦法，由中央主管機關定之。"}],"44":[{"i":0,"t":"中央主管機關應於收到裁決申請書之日起七日內，召開裁決委員會處理之。"},{"i":0,"t":"裁決委員會應指派委員一人至三人，依職權調查事實及必要之證據，並應於指派後二十日內作成調查報告，必要時得延長二十日。"},{"i":0,"t":"裁決委員調查或裁決委員會開會時，應通知當事人、相關人員或事業單位以言詞或書面提出說明；裁決委員為調查之必要，得經主管機關同意，進入相關事業單位訪查。"},{"i":0,"t":"前項受通知或受訪查人員，不得為虛偽說明、提供不實資料或無正當理由拒絕說明。"},{"i":0,"t":"申請人經依第三項規定通知，無正當理由二次不到場者，視為撤回申請；相對人二次不到場者，裁決委員會得經到場一造陳述為裁決。"},{"i":0,"t":"裁決當事人就同一爭議事件達成和解或經法定調解機關調解成立者，裁決委員會應作成不受理之決定。"}],"45":[{"i":0,"t":"主任裁決委員應於裁決委員作成調查報告後七日內，召開裁決委員會，並於開會之日起三十日內作成裁決決定。但經裁決委員會應出席委員二分之一以上同意者得延長之，最長以三十日為限。"}],"46":[{"i":0,"t":"裁決委員會應有三分之二以上委員出席，並經出席委員二分之一以上同意，始得作成裁決決定；作成裁決決定前，應由當事人以言詞陳述意見。"},{"i":0,"t":"裁決委員應親自出席，不得委任他人代理。"},{"i":0,"t":"裁決委員審理案件相關給付報酬標準，由中央主管機關定之。"}],"47":[{"i":0,"t":"裁決決定書應載明下列事項："},{"i":4,"t":"一、當事人姓名、住所或居所；如為法人、雇主團體或工會，其名稱、代表人及主事務所或主營業所。"},{"i":4,"t":"二、有代理人者，其姓名、名稱及住居所或事務所。"},{"i":4,"t":"三、主文。"},{"i":4,"t":"四、事實。"},{"i":4,"t":"五、理由。"},{"i":4,"t":"六、主任裁決委員及出席裁決委員之姓名。"},{"i":4,"t":"七、年、月、日。"},{"i":0,"t":"裁決委員會作成裁決決定後，中央主管機關應於二十日內將裁決決定書送達當事人。"}],"47-1":[{"i":0,"t":"中央主管機關應以定期出版、登載於網站或其他適當方式公開裁決決定書。但裁決決定書含有依政府資訊公開法應限制公開或不予提供之事項者，應僅就其他部分公開之。"},{"i":0,"t":"前項公開，得不含自然人之名字、身分證統一編號及其他足資識別該個人之資料。但應公開自然人之姓氏及足以區辨人別之代稱。"}],"48":[{"i":0,"t":"對工會法第三十五條第二項規定所生民事爭議事件所為之裁決決定，當事人於裁決決定書正本送達三十日內，未就作為裁決決定之同一事件，以他方當事人為被告，向法院提起民事訴訟者，或經撤回其訴者，視為雙方當事人依裁決決定書達成合意。"},{"i":0,"t":"裁決經依前項規定視為當事人達成合意者，裁決委員會應於前項期間屆滿後七日內，將裁決決定書送請裁決委員會所在地之法院審核。"},{"i":0,"t":"前項裁決決定書，法院認其與法令無牴觸者，應予核定，發還裁決委員會送達當事人。"},{"i":0,"t":"法院因裁決程序或內容與法令牴觸，未予核定之事件，應將其理由通知裁決委員會。但其情形可以補正者，應定期間先命補正。"},{"i":0,"t":"經法院核定之裁決有無效或得撤銷之原因者，當事人得向原核定法院提起宣告裁決無效或撤銷裁決之訴。"},{"i":0,"t":"前項訴訟，當事人應於法院核定之裁決決定書送達後三十日內提起之。"}],"49":[{"i":0,"t":"前條第二項之裁決經法院核定後，與民事確定判決有同一效力。"}],"50":[{"i":0,"t":"當事人本於第四十八條第一項裁決決定之請求，欲保全強制執行或避免損害之擴大者，得於裁決決定書經法院核定前，向法院聲請假扣押或假處分。"},{"i":0,"t":"前項聲請，債權人得以裁決決定代替請求及假扣押或假處分原因之釋明，法院不得再命債權人供擔保後始為假扣押或假處分。"},{"i":0,"t":"民事訴訟法有關假扣押或假處分之規定，除第五百二十九條規定外，於前二項情形準用之。"},{"i":0,"t":"裁決決定書未經法院核定者，當事人得聲請法院撤銷假扣押或假處分之裁定。"}],"51":[{"i":0,"t":"基於工會法第三十五條第一項及團體協約法第六條第一項規定所為之裁決申請，其程序準用第三十九條、第四十條、第四十一條第一項、第四十三條至第四十七條規定。"},{"i":0,"t":"前項處分並得令當事人為一定之行為或不行為。"},{"i":0,"t":"不服第一項不受理決定者，得於決定書送達之次日起三十日內繕具訴願書，經由中央主管機關向行政院提起訴願。"},{"i":0,"t":"對於第一項及第二項之處分不服者，得於決定書送達之次日起二個月內提起行政訴訟。"}],"52":[{"i":0,"t":"本法第三十二條規定，於裁決程序準用之。"}],"53":[{"i":0,"t":"勞資爭議，非經調解不成立，不得為爭議行為；權利事項之勞資爭議，不得罷工。"},{"i":0,"t":"雇主、雇主團體經中央主管機關裁決認定違反工會法第三十五條、團體協約法第六條第一項規定者，工會得依本法為爭議行為。"}],"54":[{"i":0,"t":"工會非經會員以直接、無記名投票且經全體過半數同意，不得宣告罷工及設置糾察線。"},{"i":0,"t":"下列勞工，不得罷工："},{"i":4,"t":"一、教師。"},{"i":4,"t":"二、國防部及其所屬機關（構）、學校之勞工。"},{"i":0,"t":"下列影響大眾生命安全、國家安全或重大公共利益之事業，勞資雙方應約定必要服務條款，工會始得宣告罷工："},{"i":4,"t":"一、自來水事業。"},{"i":4,"t":"二、電力及燃氣供應業。"},{"i":4,"t":"三、醫院。"},{"i":4,"t":"四、經營銀行間資金移轉帳務清算之金融資訊服務業與證券期貨交易、結算、保管事業及其他辦理支付系統業務事業。"},{"i":0,"t":"前項必要服務條款，事業單位應於約定後，即送目的事業主管機關備查。"},{"i":0,"t":"提供固定通信業務或行動通信業務之第一類電信事業，於能維持基本語音通信服務不中斷之情形下，工會得宣告罷工。"},{"i":0,"t":"第二項及第三項所列之機關（構）及事業之範圍，由中央主管機關會同其主管機關或目的事業主管機關定之；前項基本語音通信服務之範圍，由目的事業主管機關定之。"},{"i":0,"t":"重大災害發生或有發生之虞時，各級政府為執行災害防治法所定災害預防工作或有應變處置之必要，得於災害防救期間禁止、限制或停止罷工。"}],"55":[{"i":0,"t":"爭議行為應依誠實信用及權利不得濫用原則為之。"},{"i":0,"t":"雇主不得以工會及其會員依本法所為之爭議行為所生損害為由，向其請求賠償。"},{"i":0,"t":"工會及其會員所為之爭議行為，該當刑法及其他特別刑法之構成要件，而具有正當性者，不罰。但以強暴脅迫致他人生命、身體受侵害或有受侵害之虞時，不適用之。"}],"56":[{"i":0,"t":"爭議行為期間，爭議當事人雙方應維持工作場所安全及衛生設備之正常運轉。"}],"57":[{"i":0,"t":"勞工或工會提起確認僱傭關係或給付工資之訴，暫免徵收依民事訴訟法所定裁判費之二分之一。"}],"58":[{"i":0,"t":"除第五十條第二項所規定之情形外，勞工就工資、職業災害補償或賠償、退休金或資遣費等給付，為保全強制執行而對雇主或雇主團體聲請假扣押或假處分者，法院依民事訴訟法所命供擔保之金額，不得高於請求標的金額或價額之十分之一。"}],"59":[{"i":0,"t":"勞資爭議經調解成立或仲裁者，依其內容當事人一方負私法上給付之義務，而不履行其義務時，他方當事人得向該管法院聲請裁定強制執行並暫免繳裁判費；於聲請強制執行時，並暫免繳執行費。"},{"i":0,"t":"前項聲請事件，法院應於七日內裁定之。"},{"i":0,"t":"對於前項裁定，當事人得為抗告，抗告之程序適用非訟事件法之規定，非訟事件法未規定者，準用民事訴訟法之規定。"}],"60":[{"i":0,"t":"有下列各款情形之一者，法院應駁回其強制執行裁定之聲請："},{"i":4,"t":"一、調解內容或仲裁判斷，係使勞資爭議當事人為法律上所禁止之行為。"},{"i":4,"t":"二、調解內容或仲裁判斷，與爭議標的顯屬無關或性質不適於強制執行。"},{"i":4,"t":"三、依其他法律不得為強制執行。"}],"61":[{"i":0,"t":"依本法成立之調解，經法院裁定駁回強制執行聲請者，視為調解不成立。但依前條第二款規定駁回，或除去經駁回強制執行之部分亦得成立者，不適用之。"}],"62":[{"i":0,"t":"雇主或雇主團體違反第八條規定者，處新臺幣二十萬元以上六十萬元以下罰鍰。"},{"i":0,"t":"工會違反第八條規定者，處新臺幣十萬元以上三十萬元以下罰鍰。"},{"i":0,"t":"勞工違反第八條規定者，處新臺幣一萬元以上三萬元以下罰鍰。"}],"63":[{"i":0,"t":"違反第十二條第四項、第十七條第三項、第三十三條第四項或第四十四條第四項規定，為虛偽之說明或提供不實資料者，處新臺幣三萬元以上十五萬元以下罰鍰。"},{"i":0,"t":"違反第十二條第三項、第十七條第三項、第三十三條第四項或第四十四條第四項規定，無正當理由拒絕說明或拒絕調解人或調解委員進入事業單位者，處新臺幣一萬元以上五萬元以下罰鍰。"},{"i":0,"t":"勞資雙方當事人無正當理由未依通知出席調解會議者，處新臺幣二千元以上一萬元以下罰鍰。"}],"64":[{"i":0,"t":"權利事項之勞資爭議，經依鄉鎮市調解條例調解成立者，其效力依該條例之規定。"},{"i":0,"t":"權利事項勞資爭議經當事人雙方合意，依仲裁法所為之仲裁，其效力依該法之規定。"},{"i":0,"t":"第八條之規定於前二項之調解及仲裁適用之。"}],"65":[{"i":0,"t":"為處理勞資爭議，保障勞工權益，中央主管機關應捐助設置勞工權益基金。"},{"i":0,"t":"前項基金來源如下："},{"i":4,"t":"一、勞工權益基金（專戶）賸餘專款。"},{"i":4,"t":"二、由政府逐年循預算程序之撥款。"},{"i":4,"t":"三、本基金之孳息收入。"},{"i":4,"t":"四、捐贈收入。"},{"i":4,"t":"五、其他有關收入。"}],"66":[{"i":0,"t":"本法施行日期，由行政院定之。"}]}},"L":{"name":"勞動基準法","short":"勞基法","pcode":"N0030001","arts":{"2":[{"i":0,"t":"本法用詞，定義如下："},{"i":4,"t":"一、勞工：指受雇主僱用從事工作獲致工資者。"},{"i":4,"t":"二、雇主：指僱用勞工之事業主、事業經營之負責人或代表事業主處理有關勞工事務之人。"},{"i":4,"t":"三、工資：指勞工因工作而獲得之報酬；包括工資、薪金及按計時、計日、計月、計件以現金或實物等方式給付之獎金、津貼及其他任何名義之經常性給與均屬之。"},{"i":4,"t":"四、平均工資：指計算事由發生之當日前六個月內所得工資總額除以該期間之總日數所得之金額。工作未滿六個月者，指工作期間所得工資總額除以工作期間之總日數所得之金額。工資按工作日數、時數或論件計算者，其依上述方式計算之平均工資，如少於該期內工資總額除以實際工作日數所得金額百分之六十者，以百分之六十計。"},{"i":4,"t":"五、事業單位：指適用本法各業僱用勞工從事工作之機構。"},{"i":4,"t":"六、勞動契約：指約定勞雇關係而具有從屬性之契約。"},{"i":4,"t":"七、派遣事業單位：指從事勞動派遣業務之事業單位。"},{"i":4,"t":"八、要派單位：指依據要派契約，實際指揮監督管理派遣勞工從事工作者。"},{"i":4,"t":"九、派遣勞工：指受派遣事業單位僱用，並向要派單位提供勞務者。"},{"i":4,"t":"十、要派契約：指要派單位與派遣事業單位就勞動派遣事項所訂立之契約。"}],"64":[{"i":0,"t":"雇主不得招收未滿十五歲之人為技術生。但國民中學畢業者，不在此限。"},{"i":0,"t":"稱技術生者，指依中央主管機關規定之技術生訓練職類中以學習技能為目的，依本章之規定而接受雇主訓練之人。"},{"i":0,"t":"本章規定，於事業單位之養成工、見習生、建教合作班之學生及其他與技術生性質相類之人，準用之。"}],"71":[{"i":0,"t":"工作規則，違反法令之強制或禁止規定或其他有關該事業適用之團體協約規定者，無效。"}]}},"C":{"name":"民法","short":"民法","pcode":"B0000001","arts":{"71":[{"i":0,"t":"法律行為，違反強制或禁止之規定者，無效。但其規定並不以之為無效者，不在此限。"}],"148":[{"i":0,"t":"權利之行使，不得違反公共利益，或以損害他人為主要目的。"},{"i":0,"t":"行使權利，履行義務，應依誠實及信用方法。"}],"227-2":[{"i":0,"t":"契約成立後，情事變更，非當時所得預料，而依其原有效果顯失公平者，當事人得聲請法院增、減其給付或變更其他原有之效果。"},{"i":0,"t":"前項規定，於非因契約所發生之債，準用之。"}],"250":[{"i":0,"t":"當事人得約定債務人於債務不履行時，應支付違約金。"},{"i":0,"t":"違約金，除當事人另有訂定外，視為因不履行而生損害之賠償總額。其約定如債務人不於適當時期或不依適當方法履行債務時，即須支付違約金者，債權人除得請求履行債務外，違約金視為因不於適當時期或不依適當方法履行債務所生損害之賠償總額。"}],"252":[{"i":0,"t":"約定之違約金額過高者，法院得減至相當之數額。"}]}}},"links":{"2":[{"l":0,"s":25,"e":34,"refs":[["U","6"],["U","2"]]}],"3":[{"l":0,"s":6,"e":16,"refs":[["C","71"]]}],"6":[{"l":0,"s":6,"e":12,"refs":[["C","148",2]]},{"l":10,"s":2,"e":20,"refs":[["P","51"]]},{"l":12,"s":22,"e":32,"refs":[["P","51"],["P","43"]]},{"l":12,"s":103,"e":110,"refs":[["P","26"],["P","37",2]]}],"8":[{"l":2,"s":4,"e":18,"refs":[["U","26",1,10]]}],"9":[{"l":0,"s":39,"e":50,"refs":[["U","26",1,10]]}],"12":[{"l":8,"s":5,"e":8,"refs":[["L","64"]]}],"23":[{"l":0,"s":42,"e":46,"refs":[["P","5",0,4],["P","53"]]},{"l":2,"s":42,"e":45,"refs":[["C","250"],["C","252"]]}],"31":[{"l":0,"s":7,"e":16,"refs":[["C","227-2"]]}],"32":[{"l":0,"s":17,"e":31,"refs":[["P","51"]]}]},"related":{"2":[{"law":"U","no":"5","k":1,"why":"工會任務：團體協約之締結、修改或廢止"},{"law":"P","no":"23","why":"調解成立，當事人一方為工會時視為團體協約"},{"law":"P","no":"37","p":2,"why":"調整事項之仲裁判斷視為團體協約"}],"6":[{"law":"U","no":"35","p":1,"k":3,"why":"對提出團體協商之勞工為不利待遇（不當勞動行為）"},{"law":"P","no":"53","p":2,"why":"經裁決認定違反本條第1項，工會得為爭議行為"},{"law":"P","no":"39","why":"裁決之申請期間（第51條準用）"}],"10":[{"law":"P","no":"9","p":2,"why":"第10條第2項機關（構）調解代理人應附核可機關同意書"},{"law":"P","no":"25","p":1,"why":"第10條第2項機關（構）申請仲裁須經核可"}],"14":[{"law":"U","no":"7","why":"企業工會之勞工應加入工會"},{"law":"U","no":"35","p":1,"k":2,"why":"不得以不加入工會為僱用條件"}],"19":[{"law":"L","no":"71","why":"工作規則違反團體協約者無效"}],"22":[{"law":"U","no":"35","p":2,"why":"不當勞動行為所為之解僱、降調或減薪無效"}],"23":[{"law":"P","no":"54","p":1,"why":"罷工之宣告程序"}]}};
